// Generated from the reviewed question bank. Edit the source JSON, not this file.
export default [{"id":"cie-1-001","topic":"science","level":1,"type":"choice","q":"¿Cómo respiran los tiburones bajo el agua?","why":"Las branquias sacan el oxígeno que hay en el agua. Los delfines sí usan pulmones y suben a respirar aire.","hint":"Piensa en cómo respiran los peces.","tags":["sharks","ocean"],"opts":["Con branquias","Con pulmones","Con la nariz"],"a":0},{"id":"cie-1-002","topic":"science","level":1,"type":"choice","q":"Los dinosaurios nacían de huevos.","why":"Los dinosaurios ponían huevos, igual que las aves de hoy, que son sus parientes.","hint":"Piensa en cómo nace una gallina.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-1-003","topic":"science","level":1,"type":"order","q":"Ordena estos planetas, del más cercano al Sol al más lejano.","why":"Primero está nuestro planeta, luego Marte y después Júpiter, un gigante que queda mucho más lejos del Sol.","hint":"Empieza por el planeta donde vives.","tags":["space"],"opts":["Tierra","Marte","Júpiter"]},{"id":"cie-1-004","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos es un mamífero?","why":"Los delfines respiran aire y alimentan a sus crías con leche. Los tiburones y los pulpos no.","hint":"Los mamíferos toman leche cuando son bebés.","tags":["ocean","animals"],"opts":["El pulpo","El delfín","El tiburón"],"a":1},{"id":"cie-1-005","topic":"science","level":1,"type":"choice","q":"El corazón es un músculo que bombea sangre por todo tu cuerpo.","why":"Cada latido empuja la sangre a todas partes. Es un músculo que trabaja día y noche.","hint":"Ponte la mano en el pecho y siente los latidos.","tags":["body"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-1-006","topic":"science","level":1,"type":"choice","q":"¿Qué parte de una planta absorbe el agua del suelo?","why":"Las raíces beben el agua que hay en la tierra. Las hojas, en cambio, atrapan la luz del Sol.","hint":"Es la parte que crece bajo la tierra.","tags":[],"opts":["Las hojas","Las flores","Las raíces"],"a":2},{"id":"cie-1-007","topic":"science","level":1,"type":"choice","q":"Un jugador lanza una pelota de béisbol hacia arriba. ¿Qué fuerza la hace caer?","why":"La gravedad jala todo hacia el centro de la Tierra. El viento puede mover la pelota, pero no siempre la hace caer.","hint":"Es la fuerza que te mantiene pegado al suelo.","tags":["baseball"],"opts":["El viento","La gravedad","El sonido"],"a":1},{"id":"cie-1-008","topic":"science","level":1,"type":"choice","q":"El Sol es un planeta.","why":"El Sol es una estrella. Los planetas, como la Tierra, no producen su propia luz.","hint":"Piensa en lo que brilla solo, como las estrellas de noche.","tags":["space"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-1-009","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos tiene ocho brazos?","why":"El pulpo tiene ocho brazos con ventosas. Los delfines y las tortugas marinas nadan con aletas.","hint":"Imagina cada animal y cuenta cuántos brazos tiene.","tags":["ocean","animals"],"opts":["El pulpo","El delfín","La tortuga marina"],"a":0},{"id":"cie-1-010","topic":"science","level":1,"type":"order","q":"Ordena cómo crece una mariposa, de primero a último.","why":"Del huevo sale una oruga que come y crece. Luego se encierra en una crisálida y sale convertida en mariposa.","hint":"Una oruga no vuela; una mariposa sí.","tags":["animals"],"opts":["Huevo","Oruga","Crisálida","Mariposa"]},{"id":"cie-2-001","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos tiburones es enorme, pero se alimenta filtrando plancton diminuto?","why":"Abre su enorme boca y filtra plancton. El tiburón blanco, en cambio, usa sus dientes para atrapar presas.","hint":"Pregúntate cuál de ellos no necesita dientes grandes para comer.","tags":["sharks","ocean"],"opts":["El tiburón blanco","El tiburón martillo","El tiburón ballena"],"a":2},{"id":"cie-2-002","topic":"science","level":2,"type":"choice","q":"El Tyrannosaurus rex vivió en la misma época que las primeras personas.","why":"Los dinosaurios (menos las aves) desaparecieron hace unos 66 millones de años. Las personas aparecieron muchísimo después.","hint":"Piensa en cuánto tiempo hace que no hay dinosaurios.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-2-003","topic":"science","level":2,"type":"order","q":"Ordena estos animales marinos del más pequeño al más grande.","why":"Una sardina cabe en tu mano. El tiburón blanco mide varios metros, pero la ballena azul es muchísimo más grande.","hint":"Piensa en cuál cabe en tu mano.","tags":["ocean","sharks"],"opts":["Sardina","Tiburón blanco","Ballena azul"]},{"id":"cie-2-004","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos cambios se puede deshacer enfriando?","why":"Al enfriar el agua, vuelve a ser hielo. Un pan tostado o un huevo cocinado no vuelven a ser como antes.","hint":"Piensa en cuál puedes volver a poner en el congelador.","tags":[],"opts":["Un pan que se tostó","Un hielo que se derritió","Un huevo que se cocinó"],"a":1},{"id":"cie-2-005","topic":"science","level":2,"type":"choice","q":"Los huesos de tu cuerpo están vivos.","why":"Los huesos son tejido vivo: crecen y se reparan solos cuando se rompen.","hint":"Piensa en qué pasa cuando se cura un hueso roto.","tags":["body"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-2-006","topic":"science","level":2,"type":"choice","q":"Cuando el bate golpea una pelota de béisbol, ¿qué cambia en la pelota?","why":"Un golpe es un empujón fuerte que cambia cómo se mueve la pelota. Su peso y su tamaño siguen igual.","hint":"Piensa en cómo se mueve la pelota antes y después.","tags":["baseball"],"opts":["Su dirección y su rapidez","Su peso y su color","Su tamaño y su material"],"a":0},{"id":"cie-2-007","topic":"science","level":2,"type":"choice","q":"¿Qué planeta se conoce como 'el planeta rojo'?","why":"El suelo de Marte tiene óxido de hierro, como el hierro oxidado, y por eso se ve rojizo.","hint":"Piensa en el color del polvo en ese planeta.","tags":["space"],"opts":["Venus","Júpiter","Marte"],"a":2},{"id":"cie-2-008","topic":"science","level":2,"type":"choice","q":"Un imán puede atraer una cuchara de madera.","why":"Los imanes atraen el hierro y algunos otros metales, pero no la madera.","hint":"Piensa de qué material son las cosas que se pegan a un imán.","tags":["machines"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-2-009","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos animales es un reptil?","why":"Los reptiles tienen escamas o caparazón y respiran aire. La rana es un anfibio y el delfín es un mamífero.","hint":"Los reptiles respiran aire y tienen la piel seca.","tags":["ocean","animals"],"opts":["La rana","La tortuga marina","El delfín"],"a":1},{"id":"cie-2-010","topic":"science","level":2,"type":"order","q":"Ordena cómo crece una planta con flores, de primero a último.","why":"De la semilla sale un brote, crece la planta, da flores y los frutos guardan semillas nuevas.","hint":"Todo empieza con algo pequeño bajo la tierra.","tags":[],"opts":["Semilla","Brote","Planta con flores","Fruto con semillas nuevas"]},{"id":"cie-3-001","topic":"science","level":3,"type":"choice","q":"¿De qué está hecho el esqueleto de un tiburón?","why":"El cartílago es más liviano y flexible que el hueso. Tú tienes cartílago en la nariz y en las orejas.","hint":"Toca la punta de tu nariz: ¿se dobla?","tags":["sharks"],"opts":["Cartílago flexible","Hueso duro","Concha de calcio","Escamas de piel"],"a":0},{"id":"cie-3-002","topic":"science","level":3,"type":"choice","q":"Algunos dinosaurios tenían plumas.","why":"Se han encontrado fósiles de dinosaurios con plumas. Las aves de hoy descienden de ellos.","hint":"Piensa en qué animales vivos se parecen a los dinosaurios.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-3-003","topic":"science","level":3,"type":"order","q":"Ordena las capas de la Tierra, de la superficie al centro.","why":"La corteza es la capa delgada donde vivimos. Más abajo está el manto y, en el centro, el núcleo.","hint":"Piensa en las capas de una cebolla, de afuera hacia adentro.","tags":[],"opts":["Corteza","Manto","Núcleo externo","Núcleo interno"]},{"id":"cie-3-004","topic":"science","level":3,"type":"choice","q":"¿Qué animal marino debe subir a la superficie para respirar aire?","why":"Las ballenas son mamíferos y respiran aire con pulmones. Los peces y los pulpos usan branquias.","hint":"Piensa en el chorro de agua que sale de su cabeza.","tags":["ocean","animals"],"opts":["El pulpo","La ballena","La raya","El caballito de mar"],"a":1},{"id":"cie-3-005","topic":"science","level":3,"type":"choice","q":"¿Qué instrumento usan los científicos para medir cuánta lluvia cayó?","why":"El pluviómetro recoge el agua de lluvia en un tubo con marcas. El termómetro mide la temperatura.","hint":"La palabra 'pluvial' tiene que ver con la lluvia.","tags":["weather"],"opts":["Termómetro","Brújula","Pluviómetro","Cronómetro"],"a":2},{"id":"cie-3-006","topic":"science","level":3,"type":"choice","q":"Cuando corres, tu corazón late más despacio.","why":"Al correr, tus músculos necesitan más oxígeno. Por eso el corazón late más rápido y lleva más sangre.","hint":"Piensa en lo que sientes en el pecho después de correr.","tags":["body"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-3-007","topic":"science","level":3,"type":"choice","q":"Una pelota de béisbol rueda por pasto largo y se detiene antes que sobre pasto corto. ¿Qué fuerza la frena más?","why":"El pasto largo roza más la pelota y le quita rapidez. La gravedad la jala hacia abajo, pero no la frena.","hint":"Es la fuerza que aparece cuando dos superficies se rozan.","tags":["baseball"],"opts":["El magnetismo","La gravedad","La electricidad","La fricción"],"a":3},{"id":"cie-3-008","topic":"science","level":3,"type":"order","q":"Ordena el recorrido del agua, de primero a último.","why":"El Sol calienta el agua y la convierte en vapor. Arriba el vapor se enfría, forma nubes y después llueve.","hint":"Empieza por lo que hace el Sol con el agua.","tags":["weather"],"opts":["El agua se evapora","El vapor forma nubes","La lluvia cae al suelo"]},{"id":"cie-3-009","topic":"science","level":3,"type":"number","q":"Un insecto tiene 6 patas. ¿Cuántas patas tienen 4 insectos en total?","why":"Cuatro grupos de seis patas son 24 patas. Las arañas tienen 8 patas y no son insectos.","hint":"Piensa en cuatro grupos de seis.","tags":["animals"],"a":24},{"id":"cie-3-010","topic":"science","level":3,"type":"choice","q":"¿Por qué vemos las fases de la Luna?","why":"El Sol siempre ilumina la mitad de la Luna; nosotros vemos más o menos de esa mitad. La sombra de la Tierra causa los eclipses.","hint":"Piensa en cómo cambia lo que ves de una pelota iluminada si te mueves.","tags":["space"],"opts":["La sombra de la Tierra la va tapando","Vemos distintas partes de su lado iluminado","La Luna se encoge y luego crece","Las nubes la van cubriendo cada noche"],"a":1},{"id":"cie-4-001","topic":"science","level":4,"type":"choice","q":"Los tiburones tienen unos poros en el hocico llamados ampollas de Lorenzini. ¿Para qué les sirven?","why":"Detectan los diminutos campos eléctricos que producen los animales escondidos. Respirar es trabajo de las branquias.","hint":"Es un sentido extra que nosotros no tenemos.","tags":["sharks","ocean"],"opts":["Para respirar mientras duermen","Para oír sonidos muy lejanos","Para detectar la electricidad de las presas","Para ver en la oscuridad"],"a":2,"fun":true},{"id":"cie-4-002","topic":"science","level":4,"type":"order","q":"Ordena los periodos de la era de los dinosaurios, del más antiguo al más reciente.","why":"Primero vino el Triásico, luego el Jurásico y al final el Cretácico, cuando vivió el Tyrannosaurus rex.","hint":"El Tyrannosaurus rex vivió casi al final.","tags":["dinosaurs"],"opts":["Triásico","Jurásico","Cretácico"]},{"id":"cie-4-003","topic":"science","level":4,"type":"choice","q":"El sonido viaja más rápido en el agua que en el aire.","why":"Las partículas del agua están más juntas y pasan la vibración con más rapidez. Por eso las ballenas se oyen desde lejos.","hint":"Piensa en lo que se oye cuando metes la cabeza bajo el agua.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-4-004","topic":"science","level":4,"type":"choice","q":"¿Qué causa el día y la noche en la Tierra?","why":"La Tierra da una vuelta sobre sí misma cada 24 horas. El lado que mira al Sol tiene día.","hint":"Piensa en un trompo que gira.","tags":["space"],"opts":["La Tierra gira sobre sí misma","El Sol da vueltas alrededor de la Tierra","La Luna tapa al Sol cada día","La Tierra se acerca y aleja del Sol"],"a":0},{"id":"cie-4-005","topic":"science","level":4,"type":"choice","q":"Una pelota de béisbol vuela por el aire después del golpe. ¿Qué energía tiene por estar en movimiento?","why":"Todo lo que se mueve tiene energía de movimiento, también llamada cinética. Mientras más rápido va, más tiene.","hint":"Piensa en lo que tiene un objeto que se mueve.","tags":["baseball"],"opts":["Energía de la luz","Energía del sonido","Energía de los alimentos","Energía de movimiento"],"a":3},{"id":"cie-4-006","topic":"science","level":4,"type":"choice","q":"Un pulpo tiene tres corazones.","why":"Dos corazones envían sangre a las branquias y el tercero la manda al resto del cuerpo.","hint":"Los pulpos son muy distintos a nosotros por dentro.","tags":["ocean","animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-4-007","topic":"science","level":4,"type":"order","q":"Ordena el camino de un bocado de comida por tu cuerpo.","why":"Masticas en la boca, el esófago baja la comida, el estómago la mezcla y el intestino delgado absorbe los nutrientes.","hint":"Empieza por donde entra la comida.","tags":["body"],"opts":["Boca","Esófago","Estómago","Intestino delgado"]},{"id":"cie-4-008","topic":"science","level":4,"type":"choice","q":"Un río arrastra tierra y piedritas de un lugar a otro. ¿Cómo se llama este proceso?","why":"La erosión ocurre cuando el agua, el viento o el hielo desgastan y arrastran la tierra. La evaporación solo convierte agua en vapor.","hint":"Piensa en cómo los ríos van cambiando el paisaje.","tags":[],"opts":["Erosión","Evaporación","Condensación","Hibernación"],"a":0},{"id":"cie-4-009","topic":"science","level":4,"type":"choice","q":"Para subir una caja a la misma altura, una rampa más larga necesita más fuerza que una más corta.","why":"Una rampa larga reparte el esfuerzo en más distancia. Necesitas menos fuerza, pero debes empujar más lejos.","hint":"Piensa en subir una loma por un camino largo o por uno empinado.","tags":["machines"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-4-010","topic":"science","level":4,"type":"choice","q":"Para saber si la luz ayuda a crecer a una planta, pones una al sol y otra en un clóset oscuro. ¿Qué debe ser igual en ambas?","why":"En una prueba justa solo cambias una cosa: la luz. Todo lo demás, como el agua, debe ser igual.","hint":"Solo debes cambiar una cosa a la vez.","tags":[],"opts":["La cantidad de luz","El lugar donde está cada planta","La cantidad de agua","Nada: pueden recibir cosas distintas"],"a":2},{"id":"cie-5-001","topic":"science","level":5,"type":"choice","q":"Todos los tiburones deben nadar sin parar para poder respirar.","why":"El tiburón nodriza bombea agua por sus branquias y descansa quieto en el fondo. Otros, como el blanco, sí deben nadar.","hint":"La palabra 'todos' es fuerte: busca una excepción.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-5-002","topic":"science","level":5,"type":"choice","q":"¿En qué tipo de roca es más probable encontrar un fósil de dinosaurio?","why":"Los huesos se entierran bajo capas de sedimento que se endurecen. El calor del magma destruiría un fósil.","hint":"Piensa en capas de arena y barro que se endurecen.","tags":["dinosaurs"],"opts":["Ígnea","Sedimentaria","Metamórfica","En todas por igual"],"a":1},{"id":"cie-5-003","topic":"science","level":5,"type":"order","q":"Ordena estos planetas por tamaño, del más pequeño al más grande.","why":"Mercurio y Marte son pequeños y la Tierra es mayor. Saturno y Júpiter son gigantes, y Júpiter es el más grande.","hint":"Los gigantes gaseosos son los más grandes.","tags":["space"],"opts":["Mercurio","Marte","Tierra","Saturno","Júpiter"]},{"id":"cie-5-004","topic":"science","level":5,"type":"choice","q":"En la playa, durante el día suele soplar la brisa del mar hacia la tierra. ¿Por qué?","why":"La arena se calienta más rápido que el agua. Su aire sube y el aire fresco del mar entra a ocupar su lugar.","hint":"Fíjate en qué se pone más caliente al sol: la arena o el agua.","tags":["weather","ocean"],"opts":["Las olas empujan el aire hacia la costa","La Luna jala el aire del mar","El mar se calienta antes que la arena","El aire caliente sobre la tierra sube"],"a":3},{"id":"cie-5-005","topic":"science","level":5,"type":"choice","q":"Mercurio está más cerca del Sol, pero Venus es más caliente en su superficie.","why":"La atmósfera espesa de Venus atrapa el calor como una cobija gruesa. Mercurio casi no tiene atmósfera.","hint":"Piensa en qué hace una atmósfera gruesa con el calor.","tags":["space"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-5-006","topic":"science","level":5,"type":"order","q":"Ordena las zonas del océano, desde la superficie hasta el fondo.","why":"Cada zona es más profunda y oscura que la anterior, hasta llegar al abismo, donde no llega nada de luz.","hint":"Piensa en hasta dónde llega la luz del Sol.","tags":["ocean"],"opts":["Zona de luz solar","Zona crepuscular","Zona de medianoche","El abismo"]},{"id":"cie-5-007","topic":"science","level":5,"type":"choice","q":"¿Por qué el cielo se ve azul durante el día?","why":"La luz del Sol mezcla todos los colores. El aire esparce la azul en todas direcciones, y la vemos en todo el cielo.","hint":"La luz blanca está hecha de todos los colores del arcoíris.","tags":[],"opts":["El aire dispersa más la luz azul","El cielo refleja el color de los océanos","Las moléculas del aire son de color azul","El Sol emite solamente luz de color azul"],"a":0},{"id":"cie-5-008","topic":"science","level":5,"type":"choice","q":"Lanzas una pelota de béisbol hacia arriba. ¿En qué momento su rapidez es cero, aunque sea solo un instante?","why":"La gravedad la frena mientras sube, hasta que se detiene un instante arriba. Después empieza a caer.","hint":"Piensa en el momento en que cambia de subir a bajar.","tags":["baseball"],"opts":["Justo al salir de tu mano","A mitad de camino al subir","Nunca llega a ser cero","En el punto más alto"],"a":3},{"id":"cie-5-009","topic":"science","level":5,"type":"number","q":"A las 6 a. m., un termómetro marca 4 grados bajo cero (-4 °C). Al mediodía sube 9 grados. ¿Cuántos °C marca al mediodía?","why":"Desde -4 subes 4 grados para llegar a 0 y 5 más: llegas a 5 °C.","hint":"Cuenta hacia arriba desde -4, pasando por el cero.","tags":["weather"],"a":5},{"id":"cie-5-010","topic":"science","level":5,"type":"choice","q":"¿Qué hacen los glóbulos rojos de la sangre?","why":"Los glóbulos rojos transportan oxígeno. Los glóbulos blancos combaten microbios y las plaquetas ayudan a cerrar las heridas.","hint":"Piensa en el trabajo de transporte de la sangre.","tags":["body"],"opts":["Combaten los microbios","Ayudan a que la sangre se coagule","Llevan oxígeno a todo el cuerpo","Digieren los alimentos"],"a":2},{"id":"cie-6-001","topic":"science","level":6,"type":"choice","q":"¿Con cuál de estos animales actuales tiene un parentesco más cercano el Tyrannosaurus rex?","why":"Las aves descienden de dinosaurios terópodos, el grupo del T. rex. Los cocodrilos y las lagartijas son parientes más lejanos.","hint":"Piensa en qué animales de hoy descienden de los dinosaurios.","tags":["dinosaurs","animals"],"opts":["Con un cocodrilo","Con una gallina","Con una lagartija","Con una tortuga"],"a":1,"fun":true},{"id":"cie-6-002","topic":"science","level":6,"type":"choice","q":"Sin aire, un martillo y una pluma caen a la misma rapidez.","why":"Sin aire no hay resistencia. En la Luna, un astronauta soltó un martillo y una pluma y tocaron el suelo a la vez.","hint":"Piensa en qué frena a una pluma cuando cae.","tags":["space"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-6-003","topic":"science","level":6,"type":"choice","q":"Quito está casi sobre el ecuador, pero sus noches son frescas. ¿Cuál es la razón principal?","why":"En las montañas altas el aire es más frío, incluso sobre el ecuador.","hint":"Piensa en qué pasa con el aire cuando subes una montaña.","tags":["weather"],"opts":["El Sol brilla menos allí","Está rodeada de selva","Está a gran altura sobre el mar","Está cerca de una corriente fría"],"a":2},{"id":"cie-6-004","topic":"science","level":6,"type":"order","q":"Ordena esta cadena alimentaria del mar, empezando por quien produce su propio alimento.","why":"El fitoplancton hace su alimento con luz solar. El zooplancton se lo come, la sardina come zooplancton y el tiburón come sardinas.","hint":"La energía empieza en lo que usa la luz del Sol.","tags":["ocean","sharks"],"opts":["Fitoplancton","Zooplancton","Sardina","Tiburón"]},{"id":"cie-6-005","topic":"science","level":6,"type":"choice","q":"Los músculos solo pueden jalar, no empujar. Entonces, ¿cómo estiras el codo después de doblarlo?","why":"Los músculos trabajan en pares: el bíceps dobla el codo y el tríceps lo estira.","hint":"Un músculo jala hacia un lado y otro jala hacia el contrario.","tags":["body"],"opts":["El bíceps también puede empujar el hueso","Otro músculo jala en sentido contrario","Los huesos del brazo se estiran solos","La sangre empuja el brazo hacia afuera"],"a":1},{"id":"cie-6-006","topic":"science","level":6,"type":"choice","q":"Los tiburones y los delfines tienen cuerpos de forma parecida, aunque no son parientes cercanos. ¿Por qué?","why":"Animales de grupos distintos pueden desarrollar formas parecidas si viven de modo parecido. El delfín es mamífero y respira con pulmones.","hint":"Piensa en qué forma sirve para moverse bien en el agua.","tags":["sharks","ocean"],"opts":["Los delfines descienden de los tiburones","Los dos son peces cartilaginosos","Los dos respiran con branquias","Esa forma les ayuda a nadar rápido"],"a":3},{"id":"cie-6-007","topic":"science","level":6,"type":"choice","q":"Como se venden más helados cuando hay más encuentros con tiburones, los helados atraen a los tiburones.","why":"Ambas cosas aumentan en verano porque hay más gente en la playa. Que dos cosas ocurran juntas no prueba que una cause la otra.","hint":"Pregúntate qué otra cosa podría explicar las dos.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-6-008","topic":"science","level":6,"type":"number","q":"Un satélite tarda 90 minutos en dar una vuelta completa a la Tierra. ¿Cuántas vueltas completas da en 6 horas?","why":"6 horas son 360 minutos, y 360 ÷ 90 = 4. Primero hay que usar la misma unidad.","hint":"Convierte las horas a minutos primero.","tags":["space"],"a":4},{"id":"cie-6-009","topic":"science","level":6,"type":"choice","q":"La luz del Sol tarda unos 8 minutos en llegar a la Tierra. Si el Sol desapareciera de repente, ¿cuándo dejaríamos de ver su luz?","why":"La luz que ya salió sigue viajando 8 minutos. Vemos el Sol como era hace 8 minutos.","hint":"La luz viaja muy rápido, pero no es instantánea.","tags":["space"],"opts":["Unos 8 minutos después","En ese mismo instante","Unas 8 horas después","Al día siguiente"],"a":0},{"id":"cie-6-010","topic":"science","level":6,"type":"choice","q":"Un cubo de hielo flota en un vaso con agua. ¿Cuál es la mejor explicación?","why":"Al congelarse, el agua ocupa más espacio y se vuelve menos densa, por eso flota. Así flotan los icebergs.","hint":"Compara cuánta masa cabe en el mismo espacio.","tags":["ocean"],"opts":["El hielo pesa menos que todo el vaso","Todo lo frío flota en el agua","Las burbujas de aire dentro lo sostienen","El hielo es menos denso que el agua"],"a":3},{"id":"mun-1-001","topic":"world","level":1,"type":"choice","q":"La Antártida es un continente muy frío, cubierto de hielo.","why":"La Antártida está en el polo sur y casi toda está cubierta de hielo. Allí viven pingüinos y focas.","hint":"Piensa en dónde queda el polo sur.","tags":["maps","animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-1-002","topic":"world","level":1,"type":"choice","q":"¿En qué continente está Ecuador?","why":"Ecuador está en el noroeste de América del Sur, junto al océano Pacífico.","hint":"Piensa en el continente donde está la selva del Amazonas.","tags":["maps"],"opts":["África","Asia","América del Sur"],"a":2},{"id":"mun-1-003","topic":"world","level":1,"type":"choice","q":"California y Ecuador tienen costa en el mismo océano. ¿Cuál es?","why":"Los dos están en la costa oeste de América, frente al océano Pacífico.","hint":"Mira la costa oeste de América en un mapa.","tags":["ocean","maps"],"opts":["El Pacífico","El Atlántico","El Índico"],"a":0},{"id":"mun-1-004","topic":"world","level":1,"type":"order","q":"Ordena de lo más pequeño a lo más grande.","why":"Tu casa está dentro de tu ciudad, tu ciudad dentro de un continente y los continentes están en la Tierra.","hint":"Cada lugar cabe dentro del siguiente.","tags":["maps"],"opts":["Tu casa","Tu ciudad","Un continente","La Tierra"]},{"id":"mun-1-005","topic":"world","level":1,"type":"choice","q":"¿Cuál de estas cosas es una necesidad?","why":"Una necesidad es algo que debes tener para vivir. Un videojuego es algo que quieres, pero puedes vivir sin él.","hint":"Pregúntate: ¿puedo vivir sin esto?","tags":[],"opts":["Un videojuego","Una bicicleta nueva","Agua para beber"],"a":2},{"id":"mun-1-006","topic":"world","level":1,"type":"choice","q":"La mayor parte de la superficie de la Tierra es tierra firme, no agua.","why":"Más de dos tercios de la Tierra están cubiertos por océanos. Por eso se le llama el planeta azul.","hint":"Piensa en cuánto azul ves en un globo terráqueo.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-1-007","topic":"world","level":1,"type":"choice","q":"En un mapa, ¿qué dibujo te dice dónde queda el norte?","why":"La rosa de los vientos marca el norte, el sur, el este y el oeste. La leyenda explica los símbolos.","hint":"Su nombre parece el de una flor.","tags":["maps"],"opts":["El título","La rosa de los vientos","La leyenda"],"a":1},{"id":"mun-1-008","topic":"world","level":1,"type":"choice","q":"¿Qué animal gigante es famoso en las islas Galápagos?","why":"El nombre Galápagos viene de 'galápago', una palabra antigua del español para tortuga.","hint":"Piensa en un animal lento con caparazón.","tags":["animals","ocean"],"opts":["La tortuga gigante","El elefante","El oso polar"],"a":0,"fun":true},{"id":"mun-1-009","topic":"world","level":1,"type":"choice","q":"En un desierto llueve casi todos los días.","why":"Un desierto recibe muy poca lluvia. Las selvas tropicales son las que reciben muchísima.","hint":"Piensa en un lugar con cactus y arena.","tags":["weather"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-1-010","topic":"world","level":1,"type":"choice","q":"Una isla es un pedazo de tierra rodeado de…","why":"Las islas están rodeadas de agua por todos lados, como las islas de Hawái o las Bahamas.","hint":"Piensa en cómo llegas a Hawái.","tags":["ocean","maps"],"opts":["Montañas","Desierto","Agua"],"a":2},{"id":"mun-2-001","topic":"world","level":2,"type":"choice","q":"¿Cuál de estos nombres es un continente y no un océano?","why":"África es una gran masa de tierra. El Pacífico y el Índico son océanos, extensiones enormes de agua salada.","hint":"Busca el nombre que es tierra y no agua.","tags":["maps"],"opts":["África","Pacífico","Índico"],"a":0},{"id":"mun-2-002","topic":"world","level":2,"type":"order","q":"Un bateador pega un jonrón. Ordena las bases que pisa, desde que sale del home.","why":"Los corredores recorren el cuadro en sentido contrario a las agujas del reloj, hasta volver al home.","hint":"Gira a la izquierda en cada base.","tags":["baseball","maps"],"opts":["Primera base","Segunda base","Tercera base","Home otra vez"]},{"id":"mun-2-003","topic":"world","level":2,"type":"choice","q":"Las islas de Hawái se formaron por volcanes que crecieron desde el fondo del océano.","why":"La lava se fue acumulando capa tras capa bajo el agua hasta llegar a la superficie y formar islas.","hint":"Piensa en lo que sale de un volcán.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-2-004","topic":"world","level":2,"type":"choice","q":"Miras hacia el norte y das un cuarto de vuelta a la derecha. ¿Hacia dónde miras ahora?","why":"Con el norte al frente, el este queda a tu derecha y el oeste a tu izquierda.","hint":"Dibuja la rosa de los vientos y gira con el dedo.","tags":["maps"],"opts":["Hacia el oeste","Hacia el este","Hacia el sur"],"a":1},{"id":"mun-2-005","topic":"world","level":2,"type":"choice","q":"¿Dónde hace más calor durante todo el año?","why":"Cerca del ecuador los rayos del Sol llegan más directos. El país Ecuador se llama así por esa línea.","hint":"Un país de América del Sur lleva el nombre de esta línea.","tags":["maps","weather"],"opts":["Cerca del ecuador","Cerca del polo norte","Cerca del polo sur"],"a":0},{"id":"mun-2-006","topic":"world","level":2,"type":"choice","q":"Cuando amanece, el Sol sale por el oeste.","why":"El Sol sale por el este y se oculta por el oeste, porque la Tierra gira hacia el este.","hint":"En español, el lugar donde sale el Sol se llama oriente.","tags":["space","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-2-007","topic":"world","level":2,"type":"choice","q":"En Galápagos viven iguanas que nadan en el mar. ¿Qué comen bajo el agua?","why":"Las iguanas marinas se sumergen para comer algas pegadas a las rocas. Solo viven en las islas Galápagos.","hint":"Piensa en lo que crece pegado a las rocas bajo el agua.","tags":["ocean","animals"],"opts":["Peces pequeños","Algas","Cangrejos"],"a":1},{"id":"mun-2-008","topic":"world","level":2,"type":"order","q":"Ordena de lo más antiguo a lo más nuevo.","why":"Los dinosaurios vivieron hace millones de años. Las pirámides tienen miles de años y los celulares son muy recientes.","hint":"Pregúntate qué existía antes de que hubiera personas.","tags":["dinosaurs"],"opts":["Los dinosaurios","Las pirámides de Egipto","Los teléfonos celulares"]},{"id":"mun-2-009","topic":"world","level":2,"type":"choice","q":"Machu Picchu, la antigua ciudad de piedra de los incas, está en las montañas de…","why":"Los Andes cruzan América del Sur, incluso Ecuador. Los Alpes están en Europa y el Himalaya, en Asia.","hint":"Esta cordillera también pasa por Ecuador.","tags":["maps"],"opts":["Los Alpes","El Himalaya","Los Andes"],"a":2},{"id":"mun-2-010","topic":"world","level":2,"type":"choice","q":"¿Cuál de estas cosas es un deseo y no una necesidad?","why":"Un deseo es algo que quieres, pero puedes vivir sin él. Un hogar y la ropa de abrigo son necesidades.","hint":"Un deseo es algo bonito de tener, pero no indispensable.","tags":["food"],"opts":["Un helado de chocolate","Un lugar donde dormir","Ropa para el frío"],"a":0},{"id":"mun-3-001","topic":"world","level":3,"type":"number","q":"Un puesto compra pelotas de béisbol a $3 cada una y las vende a $5 cada una. ¿Cuántos dólares de ganancia obtiene al vender 4 pelotas?","why":"Gana $2 por pelota: 5 - 3 = 2. Con 4 pelotas, 4 × 2 = $8.","hint":"Primero calcula cuánto gana por una sola pelota.","tags":["baseball","money"],"a":8},{"id":"mun-3-002","topic":"world","level":3,"type":"choice","q":"¿Para qué sirve la escala de un mapa?","why":"La escala compara la distancia en el mapa con la distancia real. El norte lo muestra la rosa de los vientos.","hint":"Piensa en '1 cm del mapa = cuántos km reales'.","tags":["maps"],"opts":["Para saber dónde queda el norte","Para calcular distancias reales","Para saber qué significan los símbolos","Para saber cuándo se hizo el mapa"],"a":1},{"id":"mun-3-003","topic":"world","level":3,"type":"choice","q":"En la Antártida viven osos polares.","why":"Los osos polares viven en el Ártico, cerca del polo norte. En la Antártida viven pingüinos y focas.","hint":"El Ártico y la Antártida están en polos opuestos.","tags":["animals","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-3-004","topic":"world","level":3,"type":"choice","q":"Las Bahamas son islas de aguas cristalinas. ¿En qué océano están?","why":"Las Bahamas están en el océano Atlántico, al este de Florida. El Pacífico queda al otro lado de América.","hint":"Piensa en qué océano baña la costa este de Estados Unidos.","tags":["ocean","maps"],"opts":["Atlántico","Pacífico","Índico","Ártico"],"a":0},{"id":"mun-3-005","topic":"world","level":3,"type":"choice","q":"Ahorrar dinero significa…","why":"Ahorrar es guardar dinero hoy para comprar algo más adelante. Gastar es usarlo ahora mismo.","hint":"Piensa en lo que se guarda en una alcancía.","tags":["money"],"opts":["Gastar todo el dinero hoy mismo","Prestar todo tu dinero a un amigo","Guardar parte del dinero para después","Cambiar billetes por monedas pequeñas"],"a":2},{"id":"mun-3-006","topic":"world","level":3,"type":"order","q":"Ordena estos cuatro océanos del más pequeño al más grande.","why":"El Ártico es el más pequeño de estos cuatro y el Pacífico, el más grande de todo el planeta.","hint":"Empieza por el océano que está cerca del polo norte.","tags":["ocean","maps"],"opts":["Ártico","Índico","Atlántico","Pacífico"]},{"id":"mun-3-007","topic":"world","level":3,"type":"choice","q":"¿Qué lugar es cálido, muy lluvioso y está lleno de plantas todo el año?","why":"En la selva tropical hace calor y llueve casi todos los días. La tundra es fría y el desierto, muy seco.","hint":"Piensa en la selva del Amazonas.","tags":["weather","animals"],"opts":["Un desierto","Una selva tropical","La tundra","Una pradera seca"],"a":1},{"id":"mun-3-008","topic":"world","level":3,"type":"choice","q":"En el noroeste del Pacífico, los salmones nadan desde el mar hasta los ríos para poner sus huevos.","why":"Muchos salmones nacen en un río, viven años en el océano y regresan a su río para reproducirse.","hint":"Piensa en peces que nadan contra la corriente de un río.","tags":["ocean","animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-3-009","topic":"world","level":3,"type":"choice","q":"Hace siglos, los marineros se guiaban con un instrumento de aguja que apunta al norte. ¿Cómo se llama?","why":"La aguja magnética de la brújula se alinea con el campo magnético de la Tierra y apunta hacia el norte.","hint":"Su aguja se mueve sola, sin que la toques.","tags":["maps"],"opts":["Termómetro","Telescopio","Brújula","Reloj de sol"],"a":2},{"id":"mun-3-010","topic":"world","level":3,"type":"choice","q":"Además del español, en los Andes de Ecuador se habla una lengua de los pueblos originarios. ¿Cuál?","why":"El kichwa es una lengua de los pueblos originarios de los Andes y se sigue hablando hoy.","hint":"Es una lengua de las montañas andinas.","tags":["maps"],"opts":["El kichwa","El maorí","El suajili","El japonés"],"a":0},{"id":"mun-4-001","topic":"world","level":4,"type":"choice","q":"Cerca de las islas Galápagos se pueden ver grandes grupos de tiburones martillo.","why":"Cerca de las islas Darwin y Wolf, en ciertas épocas se reúnen grupos de cientos de tiburones martillo.","hint":"Piensa en un archipiélago famoso por su vida marina.","tags":["sharks","ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-4-002","topic":"world","level":4,"type":"choice","q":"Cuando es verano en el hemisferio norte, ¿qué estación hay en el hemisferio sur?","why":"La Tierra está inclinada: cuando el hemisferio norte recibe más luz solar directa, el sur recibe menos.","hint":"Cuando un hemisferio se inclina hacia el Sol, el otro se aleja.","tags":["weather","maps"],"opts":["Verano","Primavera","Otoño","Invierno"],"a":3},{"id":"mun-4-003","topic":"world","level":4,"type":"choice","q":"Quedan pocas entradas para un partido de béisbol muy esperado y mucha gente quiere ir. ¿Qué suele pasar con el precio?","why":"Cuando algo escasea y mucha gente lo quiere, el precio suele subir. Se llama oferta y demanda.","hint":"Piensa en lo que pasa cuando hay pocas y muchos las quieren.","tags":["baseball","money"],"opts":["Suele bajar","Suele subir","No cambia nunca","Baja solo para los niños"],"a":1},{"id":"mun-4-004","topic":"world","level":4,"type":"order","q":"Ordena el recorrido de un río, desde su nacimiento hasta el final.","why":"El agua baja de las montañas, junta más agua y se vuelve más ancha hasta llegar al mar.","hint":"Piensa en hacia dónde fluye siempre el agua.","tags":["ocean"],"opts":["Nace en un manantial de la montaña","Baja como arroyo","Se ensancha como río","Desemboca en el mar"]},{"id":"mun-4-005","topic":"world","level":4,"type":"number","q":"En un mapa, 1 cm representa 5 km. Dos ciudades están a 6 cm en el mapa. ¿Cuántos km hay entre ellas?","why":"Cada centímetro vale 5 km, así que 6 cm son 6 × 5 = 30 km.","hint":"Multiplica los centímetros por lo que vale cada uno.","tags":["maps"],"a":30},{"id":"mun-4-006","topic":"world","level":4,"type":"choice","q":"Una península es un pedazo de tierra rodeado de agua por todos sus lados.","why":"Eso describe una isla. Una península está unida al continente por un lado y rodeada de agua por los demás.","hint":"Piensa en la diferencia entre una isla y Baja California.","tags":["maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-4-007","topic":"world","level":4,"type":"choice","q":"¿Cómo se llama la zona climática del planeta donde hace calor casi todo el año?","why":"La zona tropical es la más cálida y queda en el centro del planeta. La templada y la polar están más lejos.","hint":"Piensa en las selvas y las playas más calurosas.","tags":["weather","maps"],"opts":["La zona templada","La zona polar","La zona ártica","La zona tropical"],"a":3},{"id":"mun-4-008","topic":"world","level":4,"type":"choice","q":"Los incas construyeron una gran red de caminos de piedra que cruzaba los Andes.","why":"El Qhapaq Ñan, o camino inca, atravesaba montañas de varios países de América del Sur, incluido Ecuador.","hint":"Piensa en cómo conectaban los incas sus ciudades en las montañas.","tags":["maps"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-4-009","topic":"world","level":4,"type":"choice","q":"El monumento de la Mitad del Mundo, cerca de Quito, se construyó para señalar una línea imaginaria. ¿Cuál?","why":"El ecuador está a 0° de latitud y divide la Tierra en hemisferio norte y hemisferio sur.","hint":"Piensa en el nombre del país donde está el monumento.","tags":["maps"],"opts":["El trópico de Cáncer","El trópico de Capricornio","El ecuador","El círculo polar ártico"],"a":2},{"id":"mun-4-010","topic":"world","level":4,"type":"choice","q":"Una familia hace un presupuesto. ¿Qué es un presupuesto?","why":"Un presupuesto reparte el dinero entre gastos y ahorros. Una lista de deseos no dice cuánto dinero hay.","hint":"Un presupuesto ayuda a decidir antes de gastar.","tags":["money"],"opts":["Un plan para gastar y ahorrar","Una lista de todo lo que quieres comprar","El dinero que sobra a fin de mes","El precio más bajo de un producto"],"a":0},{"id":"mun-5-001","topic":"world","level":5,"type":"choice","q":"La Gran Muralla China se puede ver a simple vista desde la Luna.","why":"Los astronautas dicen que no se ve a simple vista desde la Luna. Es larguísima, pero muy angosta.","hint":"Piensa en lo lejos que está la Luna.","tags":["space","maps"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"mun-5-002","topic":"world","level":5,"type":"choice","q":"Cuando son las 3:00 p. m. en Los Ángeles, son las 6:00 p. m. en Nueva York. Si en Nueva York son las 9:00 p. m., ¿qué hora es en Los Ángeles?","why":"Los Ángeles va 3 horas detrás de Nueva York. Entonces, a las 9:00 p. m. allá, aquí son las 6:00 p. m.","hint":"Resta tres horas: Los Ángeles queda más al oeste.","tags":["maps"],"opts":["12:00 a. m.","9:00 p. m.","6:00 p. m.","3:00 p. m."],"a":2},{"id":"mun-5-003","topic":"world","level":5,"type":"choice","q":"¿Qué tipo de mapa usarías para ver las montañas, los ríos y los desiertos de un lugar?","why":"Un mapa físico muestra el relieve: montañas, ríos y desiertos. Un mapa de carreteras muestra rutas, no el terreno.","hint":"Piensa en el aspecto natural de la Tierra.","tags":["maps"],"opts":["Un mapa de carreteras","Un mapa del tiempo","Un mapa de husos horarios","Un mapa físico"],"a":3},{"id":"mun-5-004","topic":"world","level":5,"type":"order","q":"Ordena estas ciudades de la más cercana al ecuador a la más lejana.","why":"Quito está casi sobre el ecuador (0°). Los Ángeles queda a unos 34° norte, Seattle a unos 48° y Anchorage a unos 61°.","hint":"Piensa en cuál está más al norte en un mapa.","tags":["maps"],"opts":["Quito","Los Ángeles","Seattle","Anchorage"]},{"id":"mun-5-005","topic":"world","level":5,"type":"number","q":"Una tienda compra cada camiseta en $8 y la vende en $12. Vende 5 camisetas y paga $15 de alquiler. ¿Cuántos dólares de ganancia le quedan?","why":"Gana 12 - 8 = $4 por camiseta; con 5 son $20. Al pagar $15 de alquiler le quedan $5.","hint":"Calcula primero la ganancia de las 5 camisetas.","tags":["money"],"a":5},{"id":"mun-5-006","topic":"world","level":5,"type":"choice","q":"Los navegantes polinesios cruzaron miles de kilómetros de océano en canoas hasta llegar a Hawái. ¿Cómo se orientaban?","why":"Leían el cielo y el mar: estrellas, oleaje, vientos y vuelo de las aves. No usaban brújula ni mapas escritos.","hint":"Piensa en lo que se ve en el cielo de noche y en el mar.","tags":["ocean","maps"],"opts":["Con una brújula magnética","Con las estrellas y el oleaje","Con mapas dibujados en papel","Con luces de faros en las islas"],"a":1},{"id":"mun-5-007","topic":"world","level":5,"type":"choice","q":"La Antártida es técnicamente un desierto, aunque esté cubierta de hielo.","why":"Un desierto se define por recibir muy poca lluvia o nieve, no por el calor. En la Antártida cae muy poca.","hint":"Piensa en cuánta nieve cae allí cada año.","tags":["maps","weather"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-5-008","topic":"world","level":5,"type":"choice","q":"La isla Isabela, en Galápagos, está cruzada por el ecuador, así que parte de ella está en cada hemisferio.","why":"El ecuador cruza la isla por los volcanes Wolf y Ecuador. Un trozo está en el hemisferio norte y el resto en el sur.","hint":"Piensa en la línea que divide el hemisferio norte del sur.","tags":["maps","ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-5-009","topic":"world","level":5,"type":"choice","q":"Con $10 puedes comprar una pelota de béisbol o un libro, pero no los dos. A lo que renuncias al elegir se le llama…","why":"Elegir una cosa significa renunciar a otra. El valor de lo que dejas de tener se llama costo de oportunidad.","hint":"Piensa en lo que pierdes al elegir una opción.","tags":["baseball","money"],"opts":["Costo de oportunidad","Ganancia","Ahorro","Impuesto"],"a":0},{"id":"mun-5-010","topic":"world","level":5,"type":"order","q":"Ordena estos hechos, del más antiguo al más reciente.","why":"Pirámides: hace unos 4 500 años. Imprenta: hacia 1450. Primer vuelo de los Wright: 1903. Luna: 1969.","hint":"Piensa en lo que necesita más tecnología.","tags":["space"],"opts":["Se construyen las pirámides de Egipto","Gutenberg usa su imprenta en Europa","Los hermanos Wright hacen su primer vuelo","Personas caminan sobre la Luna"]},{"id":"mun-6-001","topic":"world","level":6,"type":"number","q":"La Tierra da una vuelta completa de 360° en 24 horas. En promedio, ¿cuántos grados de longitud tiene cada huso horario?","why":"360 ÷ 24 = 15. Cada hora de diferencia equivale a unos 15 grados de longitud.","hint":"Divide los grados de una vuelta entre las horas de un día.","tags":["space","maps"],"a":15},{"id":"mun-6-002","topic":"world","level":6,"type":"choice","q":"¿Qué línea imaginaria se usa como 0° de longitud?","why":"El meridiano de Greenwich es el 0° de longitud. El ecuador es el 0° de latitud, otra medida distinta.","hint":"La longitud se mide de este a oeste, no de norte a sur.","tags":["maps"],"opts":["El ecuador","El trópico de Capricornio","El meridiano de Greenwich","La línea de cambio de fecha"],"a":2},{"id":"mun-6-003","topic":"world","level":6,"type":"choice","q":"Las estaciones del año ocurren porque la Tierra se acerca y se aleja del Sol.","why":"Se deben a la inclinación del eje terrestre. Incluso estamos más cerca del Sol en enero, en pleno invierno del norte.","hint":"Piensa en por qué hay verano en un hemisferio e invierno en el otro.","tags":["space","weather"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"mun-6-004","topic":"world","level":6,"type":"order","q":"Ordena estas ciudades de oeste a este.","why":"Honolulu está en el Pacífico, al oeste de todas. Quito queda un poco al oeste de Nueva York y Londres está cerca del meridiano 0°.","hint":"Imagina un mapamundi: el Pacífico queda a la izquierda.","tags":["maps"],"opts":["Honolulu","Los Ángeles","Quito","Nueva York","Londres"]},{"id":"mun-6-005","topic":"world","level":6,"type":"number","q":"Un banco paga $5 de interés al año por cada $100 ahorrados. Si ahorras $200 durante un año, ¿cuántos dólares tendrás al final?","why":"Por cada $100 ganas $5, así que por $200 ganas $10. Tu ahorro pasa de $200 a $210.","hint":"Calcula primero el interés de los $200.","tags":["money"],"a":210},{"id":"mun-6-006","topic":"world","level":6,"type":"choice","q":"El Niño es un cambio en el océano Pacífico. ¿Qué pasa con el agua cerca de las costas de Ecuador y Perú cuando ocurre?","why":"Durante El Niño el agua superficial se calienta, y eso cambia la lluvia y la pesca en muchos lugares del mundo.","hint":"Piensa en qué cambia en la temperatura del agua.","tags":["ocean","weather"],"opts":["Se congela en la superficie","Se vuelve mucho más salada","Se hace menos profunda","Se calienta más de lo normal"],"a":3},{"id":"mun-6-007","topic":"world","level":6,"type":"choice","q":"Una brújula apunta siempre al polo norte geográfico, el punto más al norte de la Tierra.","why":"La brújula apunta al norte magnético, que está cerca del polo norte geográfico, pero no es el mismo lugar.","hint":"Piensa en qué atrae la aguja de una brújula.","tags":["maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-6-008","topic":"world","level":6,"type":"choice","q":"¿Cuál de estas palabras del español viene del quechua, la lengua de los Andes?","why":"Papa viene del quechua. Naranja, azúcar y zanahoria llegaron del árabe, otra lengua que enriqueció al español.","hint":"Piensa en dónde nació cada alimento.","tags":["food"],"opts":["Papa","Naranja","Azúcar","Zanahoria"],"a":0,"fun":true},{"id":"mun-6-009","topic":"world","level":6,"type":"choice","q":"Las islas Galápagos están sobre el ecuador, pero allí vive un pingüino. ¿Qué hace posible que viva en un lugar tan cálido?","why":"Las corrientes frías de Humboldt y Cromwell enfrían el agua y traen peces. Sin ellas, los pingüinos no sobrevivirían allí.","hint":"Piensa en qué enfría el mar, no la tierra.","tags":["ocean","animals"],"opts":["La nieve que cubre las islas","Las corrientes frías del océano","El hielo que llega desde la Antártida","Los vientos helados del polo norte"],"a":1},{"id":"mun-6-010","topic":"world","level":6,"type":"order","q":"Ordena estas construcciones de la más antigua a la más reciente.","why":"Giza: hace unos 4 500 años. Coliseo: hacia el año 80. Machu Picchu: hacia 1450. Torre Eiffel: 1889.","hint":"Separa las de la Antigüedad de las de la época moderna.","tags":["maps"],"opts":["Pirámides de Giza","Coliseo de Roma","Machu Picchu","Torre Eiffel"]},{"id":"lec-1-001","topic":"reading","level":1,"type":"choice","q":"¿Cuál es el contrario de 'caliente'?","why":"Caliente y frío son opuestos, como el fuego y el hielo.","hint":"Piensa en un helado.","tags":[],"opts":["lento","alto","frío"],"a":2},{"id":"lec-1-002","topic":"reading","level":1,"type":"choice","q":"El dinosaurio era enorme: sus patas parecían columnas. ¿Qué significa 'enorme'?","why":"Si las patas parecen columnas, el animal es gigante. 'Enorme' quiere decir muy grande.","hint":"Las columnas son gruesas y altas.","tags":["dinosaurs"],"opts":["Muy grande","Muy rápido","Muy viejo"],"a":0},{"id":"lec-1-003","topic":"reading","level":1,"type":"choice","q":"La estrella de mar y las estrellas del cielo son lo mismo.","why":"La estrella de mar es un animal del océano; las del cielo son soles muy lejanos.","hint":"Piensa dónde vive cada una.","tags":["ocean","space"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"lec-1-004","topic":"reading","level":1,"type":"choice","q":"El corredor del equipo es muy veloz. ¿Qué significa 'veloz'?","why":"'Veloz' y 'rápido' significan casi lo mismo: se mueve con mucha velocidad.","hint":"Imagina al corredor llegando a la base.","tags":["baseball"],"opts":["Cansado","Rápido","Alto"],"a":1},{"id":"lec-1-005","topic":"reading","level":1,"type":"choice","q":"Sofía abrió el paraguas y se puso las botas de lluvia. ¿Qué tiempo hacía?","why":"El paraguas y las botas de lluvia se usan cuando llueve.","hint":"Mira lo que se puso Sofía.","tags":["weather"],"opts":["Hacía mucho sol","Llovía","Era de noche"],"a":1},{"id":"lec-1-006","topic":"reading","level":1,"type":"order","q":"Ordena la historia de Ana y la semilla.","why":"Las palabras primero, después, luego y al final marcan el orden.","hint":"Busca las palabras que marcan el orden.","tags":[],"opts":["Primero, Ana compró una semilla.","Después, la plantó en la tierra.","Luego, la regó todos los días.","Al final, salió una flor."]},{"id":"lec-1-007","topic":"reading","level":1,"type":"choice","q":"Tomás perdió su guante de béisbol y se sentó en el suelo con la cabeza baja. ¿Cómo se sentía?","why":"Sentarse en el suelo con la cabeza baja son pistas de tristeza.","hint":"Fíjate en cómo tiene la cabeza.","tags":["baseball"],"opts":["Contento","Triste","Sorprendido"],"a":1},{"id":"lec-1-008","topic":"reading","level":1,"type":"choice","q":"El bate, la pelota y el guante son cosas de un deporte. ¿De cuál?","why":"El bate, la pelota y el guante se usan en el béisbol.","hint":"Piensa en un estadio con bases.","tags":["baseball"],"opts":["Béisbol","Natación","Ciclismo"],"a":0},{"id":"lec-1-009","topic":"reading","level":1,"type":"number","q":"'El pulpo, el delfín y la tortuga nadan en el mar.' ¿Cuántos animales aparecen en la oración?","why":"Los animales son el pulpo, el delfín y la tortuga. El mar no es un animal.","hint":"Cuenta solo los animales.","tags":["ocean"],"a":3},{"id":"lec-1-010","topic":"reading","level":1,"type":"choice","q":"Los pulpos tienen ocho brazos. Con ellos agarran comida y caminan por el fondo del mar. ¿De qué trata el texto?","why":"Todo el texto habla del pulpo y de sus brazos.","hint":"¿Qué animal se repite en todo el texto?","tags":["ocean"],"opts":["De cómo se construye un barco","De los peces que viven en ríos","Del pulpo"],"a":2},{"id":"lec-2-001","topic":"reading","level":2,"type":"choice","q":"El tiburón nadaba silencioso entre las rocas. ¿Qué significa 'silencioso'?","why":"Silencioso viene de silencio: no se oye ningún ruido.","hint":"Mira la palabra 'silencio' dentro.","tags":["sharks"],"opts":["Con mucha hambre","Muy rápido","Sin hacer ruido"],"a":2},{"id":"lec-2-002","topic":"reading","level":2,"type":"choice","q":"El jugador ____ a toda velocidad hacia la base. ¿Qué verbo encaja mejor?","why":"'A toda velocidad' pide un verbo de rapidez: corrió. Pasear y gatear son lentos.","hint":"Busca el verbo más veloz.","tags":["baseball"],"opts":["corrió","paseó despacio","gateó sin prisa"],"a":0},{"id":"lec-2-003","topic":"reading","level":2,"type":"choice","q":"'Alegre' y 'triste' significan casi lo mismo.","why":"Son antónimos: alegre es contento y triste es lo contrario.","hint":"Piensa en la cara de cada uno.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-2-004","topic":"reading","level":2,"type":"choice","q":"¿Cuál es el contrario de 'despegar', cuando hablamos de un cohete?","why":"El cohete despega para subir y aterriza para bajar y posarse.","hint":"Piensa en cómo termina un viaje.","tags":["space"],"opts":["Sobrevolar","Orbitar","Aterrizar"],"a":2},{"id":"lec-2-005","topic":"reading","level":2,"type":"choice","q":"Lucas guardó sus guantes en la mochila y bostezó. Mamá apagó la luz de su cuarto. ¿Qué iba a hacer Lucas?","why":"Bostezar y apagar la luz son pistas de que es hora de dormir.","hint":"¿Qué se hace cuando se apaga la luz?","tags":[],"opts":["Dormir","Jugar béisbol","Desayunar"],"a":0},{"id":"lec-2-006","topic":"reading","level":2,"type":"order","q":"Ordena estos animales del más pequeño al más grande.","why":"Un ratón cabe en la mano; la ballena azul es más grande que cualquier elefante.","hint":"Empieza por el que cabe en tu mano.","tags":["animals","ocean"],"opts":["ratón","perro","elefante","ballena azul"],"fun":true},{"id":"lec-2-007","topic":"reading","level":2,"type":"choice","q":"El primer día de clases, Pablo no soltaba la mano de su mamá. ¿Cómo se sentía?","why":"No soltar la mano de mamá muestra nervios ante algo nuevo.","hint":"Piensa en lo que sientes con algo nuevo.","tags":[],"opts":["Aburrido","Nervioso","Orgulloso"],"a":1},{"id":"lec-2-008","topic":"reading","level":2,"type":"choice","q":"El buzo explora el fondo del mar. ¿Qué hace un 'buzo'?","why":"Un buzo es una persona que baja y trabaja bajo el agua.","hint":"Piensa en dónde está el fondo del mar.","tags":["ocean"],"opts":["Vuela en cohete","Nada bajo el agua","Maneja un barco grande"],"a":1},{"id":"lec-2-009","topic":"reading","level":2,"type":"number","q":"'Hay tres tiburones y dos delfines en la bahía.' ¿Cuántos animales hay en total?","why":"Tres tiburones más dos delfines son cinco animales en la bahía.","hint":"Suma los dos grupos.","tags":["sharks","ocean"],"a":5},{"id":"lec-2-010","topic":"reading","level":2,"type":"choice","q":"Hoy no hubo práctica de béisbol porque llovió toda la tarde. ¿Por qué no hubo práctica?","why":"La palabra 'porque' señala la causa: llovió toda la tarde.","hint":"Busca la palabra 'porque'.","tags":["baseball","weather"],"opts":["Porque hacía calor","Porque se rompió el bate","Porque llovió"],"a":2},{"id":"lec-3-001","topic":"reading","level":3,"type":"choice","q":"La tortuga marina avanzaba despacio por la arena, con mucho cuidado. ¿Qué palabra significa lo mismo que 'despacio'?","why":"Despacio y lentamente significan que se hace con poca velocidad.","hint":"Piensa en cómo se mueve una tortuga.","tags":["ocean"],"opts":["lentamente","rápidamente","ruidosamente","alegremente"],"a":0},{"id":"lec-3-002","topic":"reading","level":3,"type":"choice","q":"El astrónomo ____ la Luna con su telescopio durante horas, con mucha atención. ¿Qué verbo encaja mejor?","why":"'Durante horas' y 'con atención' piden observar: mirar con cuidado.","hint":"Busca el verbo para mirar con mucha atención.","tags":["space"],"opts":["echó un vistazo a","vio de pasada","miró de reojo","observó"],"a":3},{"id":"lec-3-003","topic":"reading","level":3,"type":"choice","q":"Un fósil es la huella o el resto de un ser vivo muy antiguo, conservado en la roca.","why":"Los fósiles de dinosaurios se encuentran en rocas muy antiguas.","hint":"Piensa en los huesos de dinosaurio de un museo.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"lec-3-004","topic":"reading","level":3,"type":"choice","q":"Los tiburones pierden dientes toda la vida, pero les crecen nuevos. Así siempre tienen dientes afilados para comer. ¿Cuál es la idea principal?","why":"La idea principal es lo que más se repite: los dientes que se renuevan.","hint":"¿De qué habla el texto en cada oración?","tags":["sharks"],"opts":["Los tiburones comen peces muy pequeños","Los dientes de los niños se caen","Los tiburones nadan muy rápido","Los tiburones renuevan sus dientes"],"a":3,"fun":true},{"id":"lec-3-005","topic":"reading","level":3,"type":"choice","q":"El lanzador tiró la pelota muy fuerte y el bateador la golpeó lejos. Todos gritaron: '¡Jonrón!'. ¿Qué pasó con la pelota?","why":"Un jonrón es cuando la pelota sale del campo por encima de la cerca.","hint":"¿Qué significa gritar 'jonrón'?","tags":["baseball"],"opts":["Salió volando del campo","Cayó en el guante del jardinero","Se quedó en la mano del lanzador","Rodó hasta la primera base"],"a":0},{"id":"lec-3-006","topic":"reading","level":3,"type":"order","q":"Ordena los momentos del día de la tortuga.","why":"Las pistas son: salió el sol, caminó, al llegar, por la noche.","hint":"Sigue el orden del día: mañana, tarde y noche.","tags":["ocean"],"opts":["El sol salió y despertó a la tortuga.","Caminó hacia el mar con pasos lentos.","Al llegar, se zambulló en las olas.","Por la noche, flotó tranquila y descansó."]},{"id":"lec-3-007","topic":"reading","level":3,"type":"choice","q":"Daniel falló el golpe y su equipo perdió. Apretó los puños, frunció el ceño y pateó el suelo. ¿Qué sentía?","why":"Puños apretados, ceño fruncido y patadas son pistas de enojo.","hint":"¿Qué emoción muestran los puños apretados?","tags":["baseball"],"opts":["Miedo","Alivio","Enojo","Aburrimiento"],"a":2},{"id":"lec-3-008","topic":"reading","level":3,"type":"choice","q":"Mi hermano duerme como un tronco. ¿Qué quiere decir esa expresión?","why":"Un tronco no se mueve; por eso 'dormir como un tronco' es dormir muy profundo.","hint":"Piensa en cuánto se mueve un tronco.","tags":[],"opts":["Duerme encima de un árbol","Duerme muy profundamente","Duerme muy poco","Duerme parado"],"a":1},{"id":"lec-3-009","topic":"reading","level":3,"type":"choice","q":"'El béisbol es el mejor deporte del mundo' es un hecho que se puede comprobar.","why":"'Mejor' depende de los gustos de cada persona. Es una opinión, no un hecho.","hint":"¿Todos piensan igual sobre el mejor deporte?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-3-010","topic":"reading","level":3,"type":"choice","q":"El telescopio sirve para ver cosas lejanas, como las estrellas. ¿Qué significa 'tele-' en esta palabra?","why":"'Tele-' significa lejos. 'Micro-' es pequeño, 'hidro-' es agua y 'bio-' es vida.","hint":"Piensa para qué sirve un telescopio.","tags":["space"],"opts":["Pequeño","Lejos","Agua","Vida"],"a":1},{"id":"lec-4-001","topic":"reading","level":4,"type":"choice","q":"El buzo vio un banco de peces plateados. En esta oración, ¿qué es un 'banco'?","why":"En el mar, un banco es un grupo grande de peces que nadan juntos.","hint":"Fíjate en que el texto habla de peces.","tags":["ocean"],"opts":["Un lugar para guardar dinero","Un grupo de peces","Un asiento largo de madera","Una roca grande y plana"],"a":1},{"id":"lec-4-002","topic":"reading","level":4,"type":"choice","q":"La serpiente ____ por la arena sin levantar el cuerpo. ¿Qué verbo es el más preciso?","why":"Las serpientes se deslizan pegadas al suelo. Saltar, trotar y trepar no describen eso.","hint":"Piensa en cómo se mueve una serpiente.","tags":["animals"],"opts":["dio saltitos","trotó muy rápido","se deslizó","trepó con fuerza"],"a":2},{"id":"lec-4-003","topic":"reading","level":4,"type":"choice","q":"'Los tiburones dan miedo' es un hecho que se puede comprobar.","why":"Dar miedo depende de cada persona. Es una opinión, no un hecho.","hint":"¿Todas las personas sienten lo mismo?","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-4-004","topic":"reading","level":4,"type":"choice","q":"El sonido viaja muy bien por el agua. Por eso las ballenas azules emiten sonidos graves que otras ballenas oyen desde muy lejos. ¿Cuál es la causa de que se oigan de lejos?","why":"La causa viene antes de 'por eso': el sonido viaja bien por el agua.","hint":"Busca la causa antes de 'por eso'.","tags":["ocean"],"opts":["El agua del mar está muy caliente","Las ballenas tienen orejas enormes","Las ballenas cantan solo en tormentas","El sonido viaja bien por el agua"],"a":3},{"id":"lec-4-005","topic":"reading","level":4,"type":"choice","q":"'Hidro-' significa agua. ¿Qué es un 'hidroavión'?","why":"'Hidro-' viene de agua: el hidroavión se posa y despega del agua.","hint":"Une la raíz con la palabra 'avión'.","tags":["machines"],"opts":["Un avión hecho completamente de hielo","Un avión que vuela solamente de noche","Un avión que aterriza en agua","Un avión que no necesita motor"],"a":2},{"id":"lec-4-006","topic":"reading","level":4,"type":"order","q":"Ordena el nacimiento de una tortuga marina.","why":"Primero van los huevos, luego nacen, después caminan y al final nadan.","hint":"Piensa qué ocurre antes: ¿huevos o crías?","tags":["ocean"],"opts":["La mamá deja los huevos en la arena.","Después de semanas, los huevos se abren.","Las tortuguitas corren hacia el mar.","Allí empiezan a nadar."]},{"id":"lec-4-007","topic":"reading","level":4,"type":"choice","q":"Cuando dicen 'tengo mariposas en el estómago', ¿qué sienten?","why":"Es una expresión: los nervios o la emoción se sienten como aleteos en la barriga.","hint":"Piensa si hay mariposas de verdad.","tags":[],"opts":["Hambre de comer algo dulce","Nervios o emoción","Frío en todo el cuerpo","Sueño y ganas de dormir"],"a":1},{"id":"lec-4-008","topic":"reading","level":4,"type":"choice","q":"¿Cuál de estas frases es un HECHO?","why":"Un hecho se puede comprobar. 'Bonito', 'aburrido' y 'genial' son opiniones.","hint":"Un hecho se puede comprobar con pruebas.","tags":["space"],"opts":["La Tierra gira alrededor del Sol","La Luna es lo más bonito del cielo","Marte es el planeta más aburrido","Vivir en el espacio sería genial"],"a":0},{"id":"lec-4-009","topic":"reading","level":4,"type":"choice","q":"La palabra 'murciélago' tiene las cinco vocales: a, e, i, o, u.","why":"Mur-cié-la-go tiene u, i, e, a, o. Es una de las pocas palabras con todas las vocales.","hint":"Escribe la palabra y marca las vocales.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-4-010","topic":"reading","level":4,"type":"choice","q":"El cielo se puso muy gris, el viento sopló fuerte y los pájaros volaron a sus nidos. ¿Qué iba a pasar pronto?","why":"Cielo gris y viento fuerte son pistas de tormenta. Una sequía es falta de lluvia.","hint":"Piensa qué anuncian las nubes grises y el viento.","tags":["weather"],"opts":["Una tormenta","Un eclipse solar","Una gran sequía","Un amanecer rojo"],"a":0},{"id":"lec-5-001","topic":"reading","level":5,"type":"choice","q":"Todos hablaron del jonrón que ganó el partido en la última entrada: fue un golpe memorable. ¿Qué significa 'memorable'?","why":"Memorable viene de memoria: algo que vale la pena recordar.","hint":"Piensa en la palabra 'memoria'.","tags":["baseball"],"opts":["Digno de ser recordado","Muy suave y demasiado lento","Lleno de errores y fallas","Imposible de ver desde lejos"],"a":0},{"id":"lec-5-002","topic":"reading","level":5,"type":"choice","q":"En el desierto el agua es escasa. ¿Cuál es el antónimo de 'escasa'?","why":"Escasa significa poca. Su contrario es abundante: mucha. Las otras tres son sinónimos de escasa.","hint":"Busca el que significa mucha cantidad.","tags":[],"opts":["limitada","insuficiente","reducida","abundante"],"a":3},{"id":"lec-5-003","topic":"reading","level":5,"type":"choice","q":"La palabra 'astronauta' significa 'navegante de los océanos'.","why":"Astro es estrella y nauta, navegante. El astronauta es un navegante de las estrellas.","hint":"Fíjate en la raíz 'astro'.","tags":["space"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-5-004","topic":"reading","level":5,"type":"choice","q":"Ese bateador tiene ojo de águila: no se le escapa ninguna pelota. ¿Qué quiere decir esa expresión?","why":"'Ojo de águila' se dice de quien ve y se da cuenta de todo, como un águila.","hint":"Las águilas ven desde muy lejos.","tags":["baseball"],"opts":["Tiene un ojo lastimado","Es muy bravo y agresivo","Lleva lentes especiales","Observa y nota todo"],"a":3},{"id":"lec-5-005","topic":"reading","level":5,"type":"choice","q":"¿Qué enseña el refrán 'Camarón que se duerme, se lo lleva la corriente'?","why":"Es una metáfora: quien se descuida pierde su oportunidad, como el camarón dormido.","hint":"No habla de camarones de verdad.","tags":["ocean"],"opts":["Los camarones nadan mejor cuando oscurece del todo","Hay que estar atentos y aprovechar oportunidades","Hay que dormir mucho para tener más energía","Las corrientes del mar siempre son peligrosas"],"a":1},{"id":"lec-5-006","topic":"reading","level":5,"type":"order","q":"Ordena cómo se forma un fósil.","why":"Primero muere, luego lo cubre el barro, el barro se endurece y mucho después aparece.","hint":"Piensa en lo que ocurre antes de ser enterrado.","tags":["dinosaurs"],"opts":["Un dinosaurio muere cerca de un río.","El barro cubre sus huesos.","El barro se endurece y se vuelve roca.","Millones de años después, alguien encuentra el fósil."]},{"id":"lec-5-007","topic":"reading","level":5,"type":"choice","q":"Inés aplaudió y sonrió cuando dijeron el nombre de su amiga, pero se mordió el labio y bajó la mirada. ¿Qué sentía?","why":"Aplaudir y sonreír muestran alegría; morderse el labio y bajar la mirada, decepción.","hint":"Hay dos pistas distintas: lo que hace al principio y al final.","tags":[],"opts":["Muy enojada con su amiga por haber ganado","Contenta por su amiga y algo decepcionada","Aburrida y sin ninguna gana de aplaudir","Orgullosa de haber ganado ella misma el premio"],"a":1},{"id":"lec-5-008","topic":"reading","level":5,"type":"choice","q":"'Bio' significa vida y 'grafía', escritura. ¿Qué es una 'biografía'?","why":"Bio (vida) + grafía (escritura): la biografía cuenta la vida de una persona.","hint":"Une los significados de las dos partes.","tags":[],"opts":["Un libro de dibujos de animales","Un mapa que muestra el cuerpo","El relato de la vida de alguien","Una carta escrita a un amigo"],"a":2},{"id":"lec-5-009","topic":"reading","level":5,"type":"choice","q":"Los pulpos tienen tres corazones.","why":"Dos corazones envían sangre a las branquias y el tercero, al resto del cuerpo.","hint":"Piensa en el cuerpo tan raro de los pulpos.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-5-010","topic":"reading","level":5,"type":"choice","q":"Un cometa se acerca al Sol y su hielo se calienta. Por eso se forma una cola brillante. ¿Cuál es la causa de la cola?","why":"La causa va antes de 'por eso': el hielo se calienta y forma la cola.","hint":"Busca la causa antes de 'por eso'.","tags":["space"],"opts":["La Luna empuja el cometa hacia afuera","Los cometas giran muy rápido sobre sí mismos","El hielo se calienta cerca del Sol","El cometa se enfría en el espacio"],"a":2},{"id":"lec-6-001","topic":"reading","level":6,"type":"choice","q":"Los científicos hicieron una hipótesis: el megalodón desapareció porque el mar se enfrió y su comida escaseó. ¿Qué es una hipótesis?","why":"Una hipótesis es una posible explicación que luego se prueba con evidencias.","hint":"Los científicos la prueban después.","tags":["sharks"],"opts":["Una explicación que se puede probar","Un dato que ya se comprobó hace años","Un dibujo científico del animal extinto","Una opinión que nunca se puede probar"],"a":0},{"id":"lec-6-002","topic":"reading","level":6,"type":"choice","q":"Algunas flores de cactus son efímeras: duran solo un día. ¿Qué palabra significa lo CONTRARIO de 'efímera'?","why":"Efímera es lo que dura poco; su contrario es duradera. Fugaz es sinónimo de efímera.","hint":"Busca la que significa 'dura mucho'.","tags":[],"opts":["Fugaz","Delicada","Duradera","Colorida"],"a":2},{"id":"lec-6-003","topic":"reading","level":6,"type":"choice","q":"'Hipopótamo' viene del griego y significa 'caballo de río'.","why":"Hippos es caballo y potamós, río. Los antiguos griegos lo llamaron así.","hint":"Piensa en dónde pasa el día este animal.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-6-004","topic":"reading","level":6,"type":"choice","q":"'A buen entendedor, pocas palabras bastan' significa que...","why":"Al que entiende pronto le bastan pocas palabras. No hace falta explicarle de más.","hint":"Fíjate en quién es el 'buen entendedor'.","tags":[],"opts":["Para convencer a alguien hay que repetir mucho","Entender bien cuesta muchas palabras difíciles","Quien entiende rápido no necesita más palabras","Los que hablan poco entienden menos cosas"],"a":2},{"id":"lec-6-005","topic":"reading","level":6,"type":"choice","q":"—¡Qué día tan perfecto! —suspiró Pablo, mientras la lluvia le mojaba el uniforme y suspendían el partido de béisbol. ¿Qué quiso decir Pablo?","why":"Es ironía: dice una cosa para dar a entender lo contrario, y la situación lo muestra.","hint":"Compara lo que dice con lo que le pasa.","tags":["baseball","weather"],"opts":["Que estaba feliz de que lloviera tanto","Que el partido sería mucho mejor mojado","Que no le importaba nada el partido","Lo contrario: el día era malo"],"a":3},{"id":"lec-6-006","topic":"reading","level":6,"type":"order","q":"Ordena estos vientos del más suave al más fuerte.","why":"Una brisa apenas mueve las hojas; el ventarrón es muy fuerte y el huracán es aún más.","hint":"Empieza por el que apenas mueve las hojas.","tags":["weather"],"opts":["brisa","viento","ventarrón","huracán"]},{"id":"lec-6-007","topic":"reading","level":6,"type":"choice","q":"Hallaron fósiles de peces en la cima de una montaña muy alta. ¿Qué se puede deducir?","why":"Los fósiles marinos en montañas indican que esa tierra estuvo cubierta por el mar y luego se elevó.","hint":"Piensa dónde vivían esos peces.","tags":["ocean"],"opts":["Que esa tierra estuvo bajo el mar","Que unos pescadores los dejaron allí","Que los peces antiguos vivían en tierra firme","Que son rocas con forma de pez"],"a":0,"fun":true},{"id":"lec-6-008","topic":"reading","level":6,"type":"choice","q":"¿Cuál de estas palabras expresa el miedo MÁS intenso?","why":"Pavor es un miedo muy fuerte. Inquietud y recelo son más suaves.","hint":"Ordena mentalmente de miedo leve a miedo enorme.","tags":[],"opts":["Inquietud","Recelo","Temor","Pavor"],"a":3},{"id":"lec-6-009","topic":"reading","level":6,"type":"choice","q":"Los tiburones ya nadaban en los mares antes de que existieran los dinosaurios.","why":"Los antepasados de los tiburones aparecieron hace unos 400 millones de años; los dinosaurios, hace unos 230.","hint":"Compara hace cuánto tiempo apareció cada uno.","tags":["sharks","dinosaurs"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-6-010","topic":"reading","level":6,"type":"choice","q":"Algunas plantas atrapan insectos. La planta carnívora cierra sus hojas como una trampa y así obtiene nutrientes que el suelo pobre no le da. ¿Cuál es la idea central?","why":"La idea central abarca todo el texto. 'Todas las plantas' exagera: dice 'algunas'.","hint":"Cuidado con las opciones que dicen 'todas'.","tags":[],"opts":["Los insectos prefieren vivir en suelos pobres","Algunas plantas cazan insectos para nutrirse","Las hojas se cierran cuando llega la noche","Todas las plantas necesitan comer insectos"],"a":1},{"id":"pal-1-001","topic":"words","level":1,"type":"choice","q":"¿Cuál es el plural de 'pez'?","why":"Si una palabra termina en z, la z cambia a c antes de -es: pez, peces.","hint":"Recuerda qué letra cambia cuando una palabra termina en z.","tags":["ocean"],"opts":["pezes","peses","peces"],"a":2},{"id":"pal-1-002","topic":"words","level":1,"type":"choice","q":"¿Qué artículo va con la palabra 'delfín'? ____ delfín nada en el mar.","why":"Delfín es masculino y está en singular: el delfín. 'La' y 'Las' son femeninos.","hint":"Es un solo delfín, y es masculino.","tags":["ocean"],"opts":["La","El","Las"],"a":1},{"id":"pal-1-003","topic":"words","level":1,"type":"choice","q":"'Bate' rima con 'pelota'.","why":"Bate termina en -ate y pelota termina en -ota. No suenan igual al final.","hint":"Compara los sonidos del final de cada palabra.","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-1-004","topic":"words","level":1,"type":"choice","q":"¿Cuál es el diminutivo de 'gato'?","why":"Los diminutivos terminan en -ito o -ita y dicen que algo es pequeño. 'Gatazo' es aumentativo.","hint":"Busca la palabra que nombra un gato pequeño.","tags":["animals"],"opts":["gatazo","gatito","gatuno"],"a":1},{"id":"pal-1-005","topic":"words","level":1,"type":"choice","q":"En 'ana juega béisbol en quito', ¿qué palabras llevan mayúscula?","why":"Los nombres propios, como Ana y Quito, llevan mayúscula. 'Béisbol' no es un nombre propio.","hint":"Mayúscula en los nombres de personas y lugares.","tags":["baseball"],"opts":["Ana y Quito","Solo Ana","Solo Quito","Béisbol y Quito"],"a":0},{"id":"pal-1-006","topic":"words","level":1,"type":"order","q":"Ordena las sílabas para formar el nombre de un animal del mar.","why":"Al unir ba-lle-na se forma 'ballena', un mamífero marino.","hint":"Es un animal enorme que sopla agua.","tags":["ocean"],"opts":["ba","lle","na"]},{"id":"pal-1-007","topic":"words","level":1,"type":"choice","q":"¿Cuál es la pregunta bien escrita?","why":"En español, las preguntas se abren con ¿ y se cierran con ?","hint":"Mira cómo empieza y cómo termina cada pregunta.","tags":[],"opts":["¿Cómo te llamas?","Cómo te llamas?","¿Cómo te llamas."],"a":0},{"id":"pal-1-008","topic":"words","level":1,"type":"choice","q":"¿Cuál palabra está bien escrita?","why":"Hormiga empieza con h muda y lleva g: hormiga.","hint":"Esta palabra empieza con una letra que no suena.","tags":["animals"],"opts":["hormiga","ormiga","hormija"],"a":0},{"id":"pal-1-009","topic":"words","level":1,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'tiburón'?","why":"Se separa ti-bu-rón: tres sílabas, una por cada vocal.","hint":"Dila despacio y cuenta los golpes de voz.","tags":["sharks"],"a":3},{"id":"pal-1-010","topic":"words","level":1,"type":"choice","q":"¿Qué palabra rima con 'estrella'?","why":"Rimar es terminar con los mismos sonidos: es-tre-lla y bo-te-lla.","hint":"Fíjate en las últimas sílabas.","tags":["space"],"opts":["montaña","cometa","botella"],"a":2},{"id":"pal-2-001","topic":"words","level":2,"type":"choice","q":"Una ____ nos da leche. ¿Cómo se escribe el animal?","why":"'Vaca' es el animal que da leche. 'Baca' es el portaequipajes de un coche.","hint":"Piensa en el significado, no en el sonido.","tags":["animals"],"opts":["vaca","baca","vacca"],"a":0},{"id":"pal-2-002","topic":"words","level":2,"type":"choice","q":"Elige la forma correcta del pez cazador de dientes afilados.","why":"Tiburón se pronuncia más fuerte al final y termina en n, por eso lleva tilde.","hint":"Di la palabra: ¿en qué sílaba suena más fuerte?","tags":["sharks"],"opts":["tiburon","tiburón","tibúron"],"a":1},{"id":"pal-2-003","topic":"words","level":2,"type":"choice","q":"La palabra 'jirafa' se escribe con j.","why":"Jirafa se escribe con j: j-i-r-a-f-a.","hint":"Es un animal de cuello muy largo.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"pal-2-004","topic":"words","level":2,"type":"choice","q":"¿Cuál es el plural de 'lápiz'?","why":"Si la palabra termina en z, cambia a c y añade -es: lápiz, lápices.","hint":"La z se transforma antes de -es.","tags":[],"opts":["lápizes","lápiz","lápices"],"a":2},{"id":"pal-2-005","topic":"words","level":2,"type":"choice","q":"Completa: Los dinosaurios ____ enormes.","why":"'Los dinosaurios' es plural, así que el verbo también debe ir en plural: eran.","hint":"El verbo debe concordar con 'los dinosaurios'.","tags":["dinosaurs"],"opts":["era","eres","eran"],"a":2},{"id":"pal-2-006","topic":"words","level":2,"type":"order","q":"Ordena alfabéticamente estos animales del mar.","why":"Orden alfabético: b, d, p, t. Se ordena por la primera letra.","hint":"Mira la primera letra de cada palabra.","tags":["ocean"],"opts":["ballena","delfín","pulpo","tiburón"]},{"id":"pal-2-007","topic":"words","level":2,"type":"choice","q":"¿Qué palabra rima con 'cohete'?","why":"Rimar es compartir los sonidos finales: cohete y juguete terminan en -ete.","hint":"Compara los últimos tres sonidos.","tags":["space"],"opts":["planeta","juguete","cometa"],"a":1},{"id":"pal-2-008","topic":"words","level":2,"type":"choice","q":"¿Cuál es el diminutivo de 'pelota'?","why":"El sufijo -ita indica pequeño. Pelotón y pelotera son otras palabras.","hint":"Busca el sufijo que significa pequeño.","tags":["baseball"],"opts":["pelotón","pelotita","pelotera"],"a":1},{"id":"pal-2-009","topic":"words","level":2,"type":"number","q":"¿Cuántas letras tiene la palabra 'delfín'?","why":"D-e-l-f-í-n: seis letras. La í con tilde sigue siendo una sola letra.","hint":"Deletrea la palabra y cuenta con los dedos.","tags":["ocean"],"a":6},{"id":"pal-2-010","topic":"words","level":2,"type":"choice","q":"¿Cuál exclamación está bien escrita?","why":"Las exclamaciones se abren con ¡ y se cierran con !","hint":"Mira el principio y el final de cada una.","tags":["baseball"],"opts":["¡Qué gran jonrón!","Qué gran jonrón!","¡Qué gran jonrón."],"a":0},{"id":"pal-3-001","topic":"words","level":3,"type":"choice","q":"Todos los días el tiburón ____ cerca de la costa. ¿Cuál es la forma correcta?","why":"Los verbos terminados en -aba llevan b y no llevan tilde: nadaba.","hint":"Recuerda la terminación del pasado de los verbos en -ar.","tags":["sharks"],"opts":["nadava","nadaba","nádaba","nadabá"],"a":1},{"id":"pal-3-002","topic":"words","level":3,"type":"choice","q":"¿Cómo se escribe un grupo de estrellas que forma un dibujo en el cielo?","why":"Las palabras terminadas en -ción llevan c y tilde en la o.","hint":"Piensa en la terminación -ción, que es una regla fija.","tags":["space"],"opts":["constelasión","constelación","constelacion","costelación"],"a":1},{"id":"pal-3-003","topic":"words","level":3,"type":"choice","q":"'Echo' es una forma del verbo hacer.","why":"Echo viene de echar (echo la pelota). La forma de hacer es 'hecho'.","hint":"Una de las dos lleva h.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-3-004","topic":"words","level":3,"type":"choice","q":"____ muchos peces en el acuario. ¿Cuál palabra completa la oración?","why":"'Hay' (del verbo haber) dice que algo existe. 'Ahí' es un lugar y 'ay' expresa dolor o sorpresa.","hint":"¿Es existencia, lugar o queja?","tags":["ocean"],"opts":["Ahí","Ay","Hai","Hay"],"a":3},{"id":"pal-3-005","topic":"words","level":3,"type":"choice","q":"¿Cómo se escribe el movimiento de las olas del mar?","why":"Las palabras terminadas en -aje llevan j: oleaje, viaje, mensaje.","hint":"Recuerda el final: -aje.","tags":["ocean"],"opts":["oleage","oleáje","oleaxe","oleaje"],"a":3},{"id":"pal-3-006","topic":"words","level":3,"type":"order","q":"Ordena las sílabas para formar el nombre de quien viaja al espacio.","why":"As-tro-nau-ta: 'nau' tiene un diptongo, que cuenta como una sola sílaba.","hint":"Es quien viaja en cohete.","tags":["space"],"opts":["as","tro","nau","ta"]},{"id":"pal-3-007","topic":"words","level":3,"type":"choice","q":"Ayer el pelotero ____ la pelota muy lejos. ¿Qué forma del verbo lanzar encaja?","why":"'Ayer' indica pasado: lanzó. 'Lanza' es presente y 'lanzará', futuro.","hint":"Busca la palabra de tiempo: 'ayer'.","tags":["baseball"],"opts":["lanza","lanzará","lanzó","lanzaría"],"a":2},{"id":"pal-3-008","topic":"words","level":3,"type":"choice","q":"¿Cuál es el aumentativo de 'perro'?","why":"Los aumentativos como -azo o -ote indican algo grande. Perrito y perrillo son diminutivos.","hint":"Busca el sufijo que significa grande.","tags":["animals"],"opts":["perrazo","perrito","perrillo","perruno"],"a":0},{"id":"pal-3-009","topic":"words","level":3,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'murciélago'?","why":"Mur-cié-la-go: 'ie' es un diptongo, así que 'cié' es una sola sílaba.","hint":"Las vocales juntas 'ie' suenan en un solo golpe.","tags":["animals"],"a":4},{"id":"pal-3-010","topic":"words","level":3,"type":"choice","q":"¿Cuál oración usa bien las comas?","why":"En una lista se separa con comas, pero no se pone coma antes de 'y'.","hint":"Separa cada animal con coma, menos el último.","tags":["ocean","sharks"],"opts":["Vi, tiburones delfines y ballenas.","Vi tiburones delfines, y ballenas.","Vi tiburones, delfines y ballenas.","Vi tiburones delfines y, ballenas."],"a":2},{"id":"pal-4-001","topic":"words","level":4,"type":"choice","q":"Un dinosaurio es un animal con columna vertebral, o sea, un ____. ¿Cómo se escribe?","why":"Vertebrado viene de vértebra. Las palabras de una misma familia conservan la v.","hint":"Piensa en la palabra 'vértebra'.","tags":["dinosaurs"],"opts":["bertebrado","vertebrado","vertevrado","vertébrado"],"a":1},{"id":"pal-4-002","topic":"words","level":4,"type":"choice","q":"Los dinosaurios nacían de un ____. ¿Cómo se escribe?","why":"Huevo empieza con hue- y lleva v. 'Hubo' es una forma del verbo haber.","hint":"Empieza con una letra muda.","tags":["dinosaurs"],"opts":["uevo","huebo","hubo","huevo"],"a":3},{"id":"pal-4-003","topic":"words","level":4,"type":"choice","q":"Todas las palabras agudas llevan tilde.","why":"Las agudas solo llevan tilde si terminan en n, s o vocal: canción sí, reloj no.","hint":"Compara 'canción' con 'reloj'.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-4-004","topic":"words","level":4,"type":"choice","q":"¿Cuál palabra está bien acentuada?","why":"'Jonrón' es aguda (suena fuerte en -rón) y termina en n: lleva tilde.","hint":"Di la palabra: ¿en qué sílaba suena más fuerte?","tags":["baseball"],"opts":["jonron","jónron","jónrón","jonrón"],"a":3},{"id":"pal-4-005","topic":"words","level":4,"type":"choice","q":"____ qué descubrió hoy el buzo en el fondo del mar. ¿Cómo se escribe el inicio?","why":"'A ver' (preposición y verbo) expresa curiosidad. 'Haber' es el verbo de 'ha habido'.","hint":"Puedes cambiarlo por 'veamos'.","tags":["ocean"],"opts":["Haber","Ha ver","A ver","Aber"],"a":2},{"id":"pal-4-006","topic":"words","level":4,"type":"order","q":"Ordena alfabéticamente estos planetas.","why":"J, M, M, V. Entre Marte y Mercurio decide la segunda letra: a va antes que e.","hint":"Si la primera letra se repite, mira la segunda.","tags":["space"],"opts":["Júpiter","Marte","Mercurio","Venus"]},{"id":"pal-4-007","topic":"words","level":4,"type":"choice","q":"Mañana los astronautas ____ a la Luna. ¿Qué forma del verbo viajar encaja?","why":"'Mañana' indica futuro, así que el verbo va en futuro: viajarán.","hint":"Busca la palabra de tiempo: 'mañana'.","tags":["space"],"opts":["viajaron","viajaban","viajarán","han viajado"],"a":2},{"id":"pal-4-008","topic":"words","level":4,"type":"choice","q":"¿Qué palabra NO pertenece a la familia de 'mar'?","why":"Marino, marea y submarino vienen de 'mar'. Marfil viene del árabe y no se relaciona con el mar.","hint":"Pregúntate cuál no tiene nada que ver con el mar.","tags":["ocean"],"opts":["marfil","marino","marea","submarino"],"a":0,"fun":true},{"id":"pal-4-009","topic":"words","level":4,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'constelación'?","why":"Cons-te-la-ción: 'ción' tiene un diptongo, así que es una sola sílaba.","hint":"Las vocales 'io' juntas suenan en un solo golpe.","tags":["space"],"a":4},{"id":"pal-4-010","topic":"words","level":4,"type":"choice","q":"En 'mañana viajamos a quito el miércoles', ¿qué palabras llevan mayúscula?","why":"Mayúscula al empezar y en nombres de ciudades. Los días de la semana van en minúscula.","hint":"¿Qué palabras son nombres propios o inician la oración?","tags":[],"opts":["Mañana y Quito","Mañana, Quito y Miércoles","Solo Quito","Quito y Miércoles"],"a":0},{"id":"pal-5-001","topic":"words","level":5,"type":"choice","q":"¿Cómo se escribe la ciencia que estudia las rocas y la historia de la Tierra?","why":"Geo- (tierra) y -logía (estudio) se escriben con g: geología, geografía, geometría.","hint":"Piensa en el prefijo que significa tierra.","tags":["space"],"opts":["jeología","geología","geolojía","jeolojía"],"a":1},{"id":"pal-5-002","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien la tilde diacrítica?","why":"'Tú' (pronombre) lleva tilde; 'tu' (posesivo) no: Tú tienes tu guante.","hint":"Un pronombre puede cambiarse por 'él' o 'ella'.","tags":["baseball"],"opts":["Tu tienes tu guante nuevo.","Tú tienes tu guante nuevo.","Tú tienes tú guante nuevo.","Tu tienes tú guante nuevo."],"a":1},{"id":"pal-5-003","topic":"words","level":5,"type":"choice","q":"En 'pingüino' la u lleva diéresis (ü) para que se pronuncie.","why":"Gue y gui suenan sin u (guitarra). Con ü se pronuncia: pingüino, cigüeña.","hint":"Compara 'guitarra' con 'pingüino'.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"pal-5-004","topic":"words","level":5,"type":"choice","q":"Los ____ llevan agua dulce de las montañas hasta el mar. ¿Cuál palabra está bien escrita?","why":"La fuerza cae en la i (rí-os), así que se separa en dos sílabas y lleva tilde.","hint":"Di la palabra: ¿la fuerza cae en la i o en la o?","tags":[],"opts":["rios","riós","ríos","ríós"],"a":2},{"id":"pal-5-005","topic":"words","level":5,"type":"choice","q":"No era un tiburón, ____ una raya. ¿Cómo se escribe?","why":"'Sino' une una idea contraria después de una negación. 'Si no' expresa condición.","hint":"Hay una negación antes y una idea contraria después.","tags":["sharks","ocean"],"opts":["si no","sinó","sí no","sino"],"a":3},{"id":"pal-5-006","topic":"words","level":5,"type":"order","q":"Pon estas palabras en orden alfabético.","why":"Compara letra por letra: tib-, til-, tiz-, tor-.","hint":"Si dos palabras empiezan igual, mira la siguiente letra.","tags":["sharks"],"opts":["tiburón","tilde","tiza","tortuga"]},{"id":"pal-5-007","topic":"words","level":5,"type":"choice","q":"Ayer yo ____ un dibujo de un megalodón. ¿Qué forma del verbo hacer encaja?","why":"El pasado de 'hacer' es irregular: yo hice, tú hiciste, él hizo.","hint":"Conjuga 'hacer' con 'yo' en pasado.","tags":["sharks"],"opts":["hice","hací","hizo","hicé"],"a":0},{"id":"pal-5-008","topic":"words","level":5,"type":"choice","q":"¿Cuál de estos prefijos significa 'debajo de'?","why":"Sub- es debajo (submarino, subsuelo). Super- es encima, inter- es entre y trans- es a través.","hint":"Prueba cada prefijo con la palabra 'marino'.","tags":["ocean"],"opts":["sub-","super-","inter-","trans-"],"a":0},{"id":"pal-5-009","topic":"words","level":5,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'electricidad'?","why":"E-lec-tri-ci-dad: cinco sílabas. En 'tri' hay tres letras pero una sola vocal.","hint":"Marca cada golpe de voz con un dedo.","tags":["machines"],"a":5},{"id":"pal-5-010","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien la coma del vocativo?","why":"El vocativo, la palabra con que llamamos a alguien, se separa con coma.","hint":"¿A quién le habla la oración?","tags":["baseball"],"opts":["Ana pásame el bate.","Ana pásame, el bate.","Ana, pásame, el bate.","Ana, pásame el bate."],"a":3},{"id":"pal-6-001","topic":"words","level":6,"type":"choice","q":"¿Cuál de estas palabras tiene un HIATO (dos vocales en sílabas distintas)?","why":"Po-e-ta tiene dos vocales abiertas juntas, que se separan. Puerta, cielo y causa tienen diptongo.","hint":"Un diptongo une una vocal abierta con una cerrada.","tags":[],"opts":["poeta","puerta","cielo","causa"],"a":0},{"id":"pal-6-002","topic":"words","level":6,"type":"choice","q":"Las palabras llanas llevan tilde cuando NO terminan en vocal, n ni s. ¿Cuál está bien escrita?","why":"Cráter es llana (CRÁ-ter) y termina en r: por eso lleva tilde.","hint":"Di la palabra: ¿en qué sílaba cae la fuerza?","tags":["space"],"opts":["crater","cratér","cráter","cráters"],"a":2},{"id":"pal-6-003","topic":"words","level":6,"type":"choice","q":"'Aun' sin tilde significa 'incluso' y 'aún' con tilde significa 'todavía'.","why":"Aún (todavía) lleva tilde: Aún no llegó. Aun (incluso) no: Aun así, lo intentó.","hint":"Prueba cambiarla por 'todavía' o por 'incluso'.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"pal-6-004","topic":"words","level":6,"type":"choice","q":"El barco navegaba ____ el puerto. ¿Cuál palabra completa la oración?","why":"'Hacia' indica dirección y no lleva tilde. 'Hacía' es del verbo hacer: hacía calor.","hint":"¿Indica dirección o es el verbo hacer?","tags":["ocean"],"opts":["hacía","hacia","asia","acia"],"a":1},{"id":"pal-6-005","topic":"words","level":6,"type":"choice","q":"¿Cómo se escribe el verbo que significa hacer una tela con hilos?","why":"Casi todos los verbos en -ger llevan g (proteger, escoger), pero tejer lleva j.","hint":"Casi todos los -ger llevan g; solo unos pocos son excepción.","tags":[],"opts":["teger","protejer","tejer","escojer"],"a":2},{"id":"pal-6-006","topic":"words","level":6,"type":"order","q":"Ordena estas cinco palabras por orden alfabético.","why":"Compara letra por letra: coh-, col-a, col-i, col-m, com-.","hint":"Si las primeras letras se repiten, compara las siguientes.","tags":["space"],"opts":["cohete","cola","colina","colmena","cometa"]},{"id":"pal-6-007","topic":"words","level":6,"type":"choice","q":"Si tuviera un telescopio, ____ los anillos de Saturno. ¿Qué forma del verbo ver encaja?","why":"Con 'si tuviera' (algo imaginado) se usa el condicional: vería.","hint":"Es algo que solo se imagina, no que ocurre.","tags":["space"],"opts":["veré","vería","he visto","veo"],"a":1},{"id":"pal-6-008","topic":"words","level":6,"type":"choice","q":"¿Cuál es el plural de 'paraguas'?","why":"Paraguas ya termina en -s y no es aguda: no cambia. Solo cambia el artículo.","hint":"Fíjate si cambia la palabra o solo el artículo.","tags":[],"opts":["los paraguases","las paraguas","los paragua","los paraguas"],"a":3},{"id":"pal-6-009","topic":"words","level":6,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'paleontología'?","why":"Pa-le-on-to-lo-gí-a: 'e-o' y 'í-a' son hiatos; cada vocal queda en una sílaba distinta.","hint":"Dos vocales abiertas juntas, o una débil con tilde, se separan.","tags":["dinosaurs"],"a":7,"fun":true},{"id":"pal-6-010","topic":"words","level":6,"type":"choice","q":"Los científicos buscan el ____ de la extinción de los dinosaurios. ¿Cómo se escribe?","why":"Con 'el' delante es un sustantivo (la razón): 'el porqué', junto y con tilde.","hint":"Fíjate en la palabra 'el' que va delante.","tags":["dinosaurs"],"opts":["porqué","por qué","porque","por que"],"a":0},{"id":"log-es-1-001","topic":"logic","level":1,"type":"choice","q":"¿Qué sigue? 🦈 🦈 🐟 🦈 🦈 ❓","why":"El patrón es dos tiburones y un pez. Ya hay dos tiburones, así que sigue el pez.","hint":"Busca el grupo que se repite.","tags":["sharks","ocean"],"opts":["🐟","🦈","🐙"],"a":0},{"id":"log-es-1-002","topic":"logic","level":1,"type":"choice","q":"Tres de estos animales viven en el mar. ¿Cuál NO vive en el mar?","why":"El pulpo y la estrella de mar viven en el mar. La jirafa vive en la tierra.","hint":"Piensa dónde vive cada animal.","tags":["ocean"],"opts":["Pulpo","Jirafa","Estrella de mar"],"a":1},{"id":"log-es-1-003","topic":"logic","level":1,"type":"number","q":"🌙 ⭐ ⭐ 🌙 ⭐ ⭐ 🌙 ⭐ ⭐  ¿Cuántas ⭐ hay en la fila?","why":"Hay tres grupos de dos estrellas: 2 + 2 + 2 = 6. Las lunas no se cuentan.","hint":"Cuenta solo las estrellas, de dos en dos.","tags":["space"],"a":6},{"id":"log-es-1-004","topic":"logic","level":1,"type":"order","q":"Ordena estas pelotas de la más pequeña a la más grande.","why":"La de golf cabe en tu mano con espacio de sobra. La de béisbol es mayor, y la de básquetbol es la más grande.","hint":"Empieza con la que podrías esconder en el puño.","tags":["baseball"],"opts":["Pelota de golf","Pelota de béisbol","Pelota de básquetbol"]},{"id":"log-es-1-005","topic":"logic","level":1,"type":"choice","q":"¿Qué color sigue? 🟥 🟦 🟦 🟥 🟦 🟦 🟥 ❓","why":"El patrón es un rojo y dos azules. Después del rojo vienen dos azules, así que sigue un azul.","hint":"Fíjate cuántos azules van después de cada rojo.","tags":[],"opts":["🟦","🟥","🟩"],"a":0},{"id":"log-es-1-006","topic":"logic","level":1,"type":"choice","q":"Verdadero o falso: después de 🔺 🔺 🔵 🔺 🔺 🔵 sigue otro 🔵.","why":"El patrón es dos triángulos y un círculo. La fila terminó en círculo, así que sigue un triángulo.","hint":"Mira cómo terminó la fila.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-1-007","topic":"logic","level":1,"type":"number","q":"Cuenta de 5 en 5: 5, 10, ❓, 20. ¿Qué número falta?","why":"Cada número es 5 más que el anterior. Después de 10 sigue 15 y luego 20.","hint":"Suma 5 cada vez.","tags":[],"a":15},{"id":"log-es-1-008","topic":"logic","level":1,"type":"choice","q":"En un equipo de béisbol, Luna es más alta que Teo. Teo es más alto que Iván. ¿Quién es la persona más baja?","why":"Luna es la más alta, Teo queda en medio e Iván es el más bajo.","hint":"Ordénalos en una fila de alto a bajo.","tags":["baseball"],"opts":["Teo","Iván","Luna"],"a":1},{"id":"log-es-1-009","topic":"logic","level":1,"type":"choice","q":"🦖 🦖 🦈 🦖  ¿Qué lugar ocupa el intruso?","why":"Tres son dinosaurios y uno es tiburón. El tiburón está en el tercer lugar.","hint":"Busca el que es diferente y cuenta desde la izquierda.","tags":["dinosaurs","sharks"],"opts":["El 1.º","El 3.º","El 4.º"],"a":1},{"id":"log-es-1-010","topic":"logic","level":1,"type":"order","q":"Ordena lo que pasa con un cohete, del primer paso al último.","why":"Primero se cuenta hacia atrás, luego despega, viaja por el espacio y al final aterriza.","hint":"Piensa qué debe pasar antes de despegar.","tags":["space"],"opts":["Cuenta regresiva","Despegue","Viaje por el espacio","Aterrizaje"]},{"id":"log-es-1-011","topic":"logic","level":1,"type":"choice","q":"¿Qué número sigue? 2, 4, 2, 4, 2, ❓","why":"El patrón alterna 2 y 4. Como el último fue 2, sigue el 4.","hint":"Fíjate en el último número y en cuál le toca.","tags":[],"opts":["2","6","4"],"a":2},{"id":"log-es-1-012","topic":"logic","level":1,"type":"number","q":"En el mar hay 5 delfines. Llegan 3 delfines más. ¿Cuántos delfines hay ahora?","why":"5 y 3 más son 8: cuenta 6, 7, 8 desde el 5.","hint":"Empieza en 5 y cuenta 3 más.","tags":["ocean","animals"],"a":8},{"id":"log-es-2-001","topic":"logic","level":2,"type":"number","q":"Cuenta hacia atrás: 50, 45, 40, 35, ❓. ¿Qué número sigue?","why":"Cada número es 5 menos que el anterior. 35 menos 5 es 30.","hint":"Mira cuánto baja cada vez.","tags":[],"a":30},{"id":"log-es-2-002","topic":"logic","level":2,"type":"choice","q":"Un paleontólogo numera los huesos de un fósil: 7, 12, 17, 22, ❓. ¿Qué número sigue?","why":"Los números suben de 5 en 5. 22 más 5 es 27.","hint":"Resta dos números vecinos para ver el salto.","tags":["dinosaurs"],"opts":["27","26","29"],"a":0},{"id":"log-es-2-003","topic":"logic","level":2,"type":"choice","q":"El tiburón A muestra 28 dientes. El tiburón B muestra 82 dientes. ¿Cuál muestra MENOS dientes?","why":"28 tiene 2 decenas y 82 tiene 8 decenas. Menos decenas significa menos dientes.","hint":"Compara primero las decenas.","tags":["sharks"],"opts":["El tiburón A","Tienen la misma cantidad","El tiburón B"],"a":0},{"id":"log-es-2-004","topic":"logic","level":2,"type":"order","q":"Cuatro cohetes llevan estos números: 46, 64, 38 y 83. Ordénalos de mayor a menor.","why":"Compara las decenas: 8 es más que 6, 6 es más que 4 y 4 es más que 3. Entre 64 y 46 gana 64.","hint":"Busca primero el número más grande.","tags":["space"],"opts":["83","64","46","38"]},{"id":"log-es-2-005","topic":"logic","level":2,"type":"choice","q":"La caja azul tiene los números impares 3, 7 y 11. ¿Qué otro número va en la caja azul?","why":"Los impares terminan en 1, 3, 5, 7 o 9. El 15 termina en 5, así que es impar.","hint":"Fíjate en el último dígito.","tags":[],"opts":["14","15","18"],"a":1},{"id":"log-es-2-006","topic":"logic","level":2,"type":"choice","q":"Verdadero o falso: si cuentas de 2 en 2 (2, 4, 6, 8…), dirás el número 15.","why":"Contando de 2 en 2 solo dices números pares. El 15 es impar, así que nunca lo dices.","hint":"Piensa si 15 es par o impar.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-2-007","topic":"logic","level":2,"type":"number","q":"Los Tigres anotaron 8 carreras. Los Leones anotaron 3 menos que los Tigres. ¿Cuántas carreras anotaron los dos equipos juntos?","why":"Los Leones anotaron 8 − 3 = 5. Juntos suman 8 + 5 = 13 carreras.","hint":"Primero averigua cuántas anotaron los Leones.","tags":["baseball"],"a":13},{"id":"log-es-2-008","topic":"logic","level":2,"type":"choice","q":"Fila 1: ⭐ 🌙 ⭐. Fila 2: 🌙 ⭐ 🌙. Fila 3: ⭐ 🌙 ❓. ¿Qué va en el espacio vacío?","why":"Cada fila y cada columna alterna entre estrella y luna. Después de ⭐ 🌙 sigue ⭐.","hint":"Mira qué hay justo arriba del espacio vacío.","tags":["space"],"opts":["⭐","🌙","☀️"],"a":0},{"id":"log-es-2-009","topic":"logic","level":2,"type":"choice","q":"Contamos de 5 en 5: 5, 10, 15, 22, 25. ¿Qué número NO pertenece?","why":"Contando de 5 en 5 solo dices números que terminan en 0 o 5. El 22 termina en 2.","hint":"Revisa el último dígito de cada número.","tags":[],"opts":["10","25","22"],"a":2},{"id":"log-es-2-010","topic":"logic","level":2,"type":"order","q":"Ordena estos dinosaurios del más pequeño al más grande.","why":"El Compsognathus era como un pollo, el Velociraptor como un pavo. El Triceratops era enorme y el Braquiosaurio todavía más.","hint":"Piensa en cuál cabría en tus brazos.","tags":["dinosaurs"],"opts":["Compsognathus","Velociraptor","Triceratops","Braquiosaurio"],"fun":true},{"id":"log-es-2-011","topic":"logic","level":2,"type":"choice","q":"¿Qué número es MAYOR que 58 y MENOR que 61?","why":"59 viene después de 58 y antes de 60 y 61. El 57 y el 62 quedan fuera.","hint":"Cuenta desde 58 hacia arriba.","tags":[],"opts":["57","62","59"],"a":2},{"id":"log-es-2-012","topic":"logic","level":2,"type":"number","q":"Cada pulpo tiene 8 brazos. Hay 2 pulpos. ¿Cuántos brazos hay en total?","why":"8 + 8 = 16 brazos. Dos grupos de 8 hacen 16.","hint":"Suma los brazos de un pulpo con los del otro.","tags":["ocean","animals"],"a":16},{"id":"log-es-3-001","topic":"logic","level":3,"type":"choice","q":"Un robot en Marte recoge rocas: 3, 7, 11, 15. Si sigue el patrón, ¿cuántas rocas recoge el día 5?","why":"El patrón suma 4 cada día. 15 más 4 es 19.","hint":"Mira cuánto crece de un día al siguiente.","tags":["space"],"opts":["17","18","19","20"],"a":2},{"id":"log-es-3-002","topic":"logic","level":3,"type":"order","q":"Colmillo es más largo que Rayo. Tito es más corto que Rayo. Dientón es más largo que Colmillo. Ordena estos tiburones del más corto al más largo.","why":"Tito queda debajo de Rayo, Rayo debajo de Colmillo y Colmillo debajo de Dientón. Une las pistas.","hint":"Dibuja una línea y coloca un tiburón a la vez.","tags":["sharks"],"opts":["Tito","Rayo","Colmillo","Dientón"]},{"id":"log-es-3-003","topic":"logic","level":3,"type":"number","q":"Un pulpo guarda perlas en cajas: 5, 9, 13, 17 y así sigue. ¿Cuántas perlas hay en la caja 6?","why":"Cada caja tiene 4 perlas más. Después de 17 vienen 21 y luego 25.","hint":"Sigue sumando el mismo número, caja por caja.","tags":["ocean"],"a":25},{"id":"log-es-3-004","topic":"logic","level":3,"type":"choice","q":"Cada fila y cada columna tiene un 🚀, una 🪐 y un ☄️. Fila 1: 🚀 🪐 ☄️. Fila 2: ☄️ 🚀 🪐. Fila 3: 🪐 ❓ 🚀. ¿Qué va en ❓?","why":"La fila 3 ya tiene 🪐 y 🚀, así que falta ☄️. La columna 2 también lo pide.","hint":"¿Qué dibujo le falta a la fila 3?","tags":["space"],"opts":["🚀","🪐","⭐","☄️"],"a":3},{"id":"log-es-3-005","topic":"logic","level":3,"type":"number","q":"El patrón ⚾ 🧢 🧢 se repite una y otra vez. Entre los primeros 12 dibujos, ¿cuántos son 🧢?","why":"12 dibujos son 4 grupos de 3. Cada grupo tiene 2 gorras: 4 × 2 = 8.","hint":"Cuenta cuántos grupos completos caben.","tags":["baseball"],"a":8},{"id":"log-es-3-006","topic":"logic","level":3,"type":"choice","q":"En un desfile de dinosaurios, el Estegosaurio camina detrás del Triceratops. El T. rex camina delante del Triceratops. ¿Quién camina en medio?","why":"La fila es T. rex, Triceratops, Estegosaurio. El Triceratops queda entre los otros dos.","hint":"Pon los tres dinosaurios en una fila.","tags":["dinosaurs"],"opts":["T. rex","Estegosaurio","No se puede saber","Triceratops"],"a":3},{"id":"log-es-3-007","topic":"logic","level":3,"type":"choice","q":"Verdadero o falso: en el patrón 40, 35, 30, 25, el siguiente número es 15.","why":"Cada número baja 5. 25 menos 5 es 20, no 15.","hint":"Calcula cuánto baja cada número.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-3-008","topic":"logic","level":3,"type":"order","q":"Resuelve cada operación y ordena los resultados de menor a mayor.","why":"Los resultados son 11, 12, 14 y 16. Ordena las respuestas, no los primeros números.","hint":"Resuelve primero y compara después.","tags":[],"opts":["20 − 9","15 − 3","9 + 5","8 + 8"]},{"id":"log-es-3-009","topic":"logic","level":3,"type":"choice","q":"Contamos de 4 en 4: 4, 8, 12, 17, 20, 24. ¿Qué número es el error?","why":"Sumando 4 cada vez da 4, 8, 12, 16, 20, 24. El 17 debería ser 16.","hint":"Suma 4 a cada número y mira dónde falla.","tags":[],"opts":["17","8","20","24"],"a":0},{"id":"log-es-3-010","topic":"logic","level":3,"type":"number","q":"En una tabla, cada fila suma 20. Fila 1: 9, 6, 5. Fila 2: 8, ❓, 7. ¿Qué número es ❓?","why":"8 + 7 = 15. Para llegar a 20 faltan 5.","hint":"Primero suma los dos números que ves.","tags":[],"a":5},{"id":"log-es-3-011","topic":"logic","level":3,"type":"choice","q":"Tres de estos animales son mamíferos que respiran aire. ¿Cuál NO lo es?","why":"Delfines, ballenas y manatíes respiran aire. El tiburón ballena es un pez y respira con branquias.","hint":"Piensa cuáles son peces y cuáles no.","tags":["sharks","ocean"],"opts":["Delfín","Ballena jorobada","Manatí","Tiburón ballena"],"a":3,"fun":true},{"id":"log-es-3-012","topic":"logic","level":3,"type":"choice","q":"¿Qué número sigue? 1, 2, 4, 7, 11, ❓","why":"Los saltos crecen: +1, +2, +3, +4. El siguiente salto es +5, y 11 + 5 = 16.","hint":"Mira cuánto sube cada vez. ¿Es siempre igual?","tags":[],"opts":["15","16","17","18"],"a":1},{"id":"log-es-4-001","topic":"logic","level":4,"type":"number","q":"Número misterioso: es mayor que 40, menor que 60, y es múltiplo de 4 y también múltiplo de 6. ¿Cuál es?","why":"48 = 4 × 12 y 48 = 6 × 8. Entre 40 y 60 ningún otro número sirve para ambos.","hint":"Busca múltiplos de 6 y revisa cuáles también son de 4.","tags":[],"a":48},{"id":"log-es-4-002","topic":"logic","level":4,"type":"choice","q":"Lu vio 3 gaviotas en la playa y las 3 eran blancas. Dice: «Todas las gaviotas del mundo son blancas.» ¿Qué falla?","why":"Tres gaviotas no muestran cómo son todas. Puede haber otras de otro color.","hint":"¿Alcanzan 3 ejemplos para hablar de todas?","tags":["animals","ocean"],"opts":["Las gaviotas siempre son negras","Tres es un número imposible","Vio muy pocas para estar segura","No falla nada"],"a":2},{"id":"log-es-4-003","topic":"logic","level":4,"type":"number","q":"Un jugador de béisbol tiene un número de camiseta de dos dígitos. Sus dígitos suman 10 y el de las decenas es 4 más que el de las unidades. ¿Qué número es?","why":"Con 7 y 3: 7 + 3 = 10 y 7 es 4 más que 3. El número es 73.","hint":"Prueba parejas de dígitos que sumen 10.","tags":["baseball"],"a":73},{"id":"log-es-4-004","topic":"logic","level":4,"type":"choice","q":"Valeria, Mateo y Camila aman cosas distintas: tiburones, dinosaurios o planetas. Valeria no ama tiburones ni dinosaurios. Mateo no ama tiburones. ¿Quién ama los tiburones?","why":"Valeria ama los planetas. Mateo no ama tiburones, así que ama dinosaurios. A Camila le tocan los tiburones.","hint":"Empieza por quien tiene más pistas.","tags":["sharks","dinosaurs","space"],"opts":["Valeria","Mateo","Camila","No se puede saber"],"a":2},{"id":"log-es-4-005","topic":"logic","level":4,"type":"order","q":"Cuatro tortugas marinas corren. Nico llega último. Luz llega justo después de Ona. Mía llega antes que Ona. Ordénalas de la primera a la última.","why":"Nico es cuarto. Mía va antes que Ona, y Luz va justo después de Ona: Mía, Ona, Luz, Nico.","hint":"Coloca primero a la que tiene un lugar seguro.","tags":["ocean"],"opts":["Mía","Ona","Luz","Nico"]},{"id":"log-es-4-006","topic":"logic","level":4,"type":"number","q":"Un cangrejo camina de A a B solo hacia la derecha o hacia abajo. B está 1 paso a la derecha y 3 pasos hacia abajo. ¿Cuántos caminos cortos distintos puede tomar?","why":"El paso a la derecha puede ser el 1.º, 2.º, 3.º o 4.º. Hay 4 caminos.","hint":"¿En qué momento da el paso a la derecha?","tags":["ocean"],"a":4},{"id":"log-es-4-007","topic":"logic","level":4,"type":"choice","q":"Verdadero o falso: todos los jugadores del equipo Rojo usan casco. Pedro usa casco, así que juega en el equipo Rojo.","why":"Jugadores de otros equipos también usan casco. La regla va del equipo Rojo al casco, no al revés.","hint":"¿Solo el equipo Rojo usa casco?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-4-008","topic":"logic","level":4,"type":"choice","q":"¿Qué número cumple TODAS las pistas? Está entre 50 y 70. Es múltiplo de 5. Sus dígitos suman más de 10.","why":"Los múltiplos de 5 son 55, 60 y 65. Solo 6 + 5 = 11 suma más de 10.","hint":"Tacha números, una pista a la vez.","tags":[],"opts":["55","60","70","65"],"a":3},{"id":"log-es-4-009","topic":"logic","level":4,"type":"number","q":"Un cohete va de la Tierra a una estación y luego a la Luna. Hay 3 rutas hasta la estación y 4 desde ella hasta la Luna. ¿Cuántas rutas hay en total?","why":"Cada ruta de las 3 se combina con 4 rutas. 3 × 4 = 12.","hint":"Para cada primera ruta, cuenta las segundas.","tags":["space"],"a":12},{"id":"log-es-4-010","topic":"logic","level":4,"type":"choice","q":"Sofía dice: «7 + 5 = 13, porque 7 + 3 = 10 y 10 + 3 = 13.» ¿Dónde está su error?","why":"Para sumar 5 se usa 3 + 2. Entonces 7 + 3 = 10 y 10 + 2 = 12.","hint":"¿Cuánto falta después de sumar 3?","tags":[],"opts":["7 + 3 no es 10","Empezó con el número equivocado","No hay ningún error","Sumó 3 otra vez en lugar de 2"],"a":3},{"id":"log-es-4-011","topic":"logic","level":4,"type":"choice","q":"Hoy es martes. El cohete despega dentro de 12 días. ¿Qué día de la semana despega?","why":"Pasan 7 días y vuelve a ser martes. Faltan 5 días más: domingo.","hint":"Cuenta primero una semana completa.","tags":["space"],"opts":["Sábado","Domingo","Lunes","Viernes"],"a":1},{"id":"log-es-4-012","topic":"logic","level":4,"type":"number","q":"Hay 12 pelotas de béisbol repartidas en 3 cajas iguales. Luego se ponen 2 pelotas más en cada caja. ¿Cuántas pelotas hay ahora en cada caja?","why":"12 pelotas entre 3 cajas son 4 en cada una. Con 2 más, quedan 6.","hint":"Primero averigua cuántas había en cada caja.","tags":["baseball"],"a":6},{"id":"log-es-5-001","topic":"logic","level":5,"type":"choice","q":"Regla del entrenador: si hay tormenta, no hay práctica. Hoy SÍ hubo práctica. ¿Qué es seguro?","why":"Si hubiera habido tormenta, no habría práctica. Como hubo práctica, no hubo tormenta.","hint":"Prueba: ¿qué habría pasado con una tormenta?","tags":["baseball","weather"],"opts":["Hubo tormenta","No hubo tormenta","Hubo mucho sol","No se puede saber"],"a":1},{"id":"log-es-5-002","topic":"logic","level":5,"type":"number","q":"Una pelota de béisbol pesa lo mismo que 2 canicas grandes. Una canica grande pesa lo mismo que 3 canicas pequeñas. ¿Cuántas canicas pequeñas pesan lo mismo que 4 pelotas?","why":"Una pelota son 2 grandes, y cada grande son 3 pequeñas: 6 pequeñas. Cuatro pelotas: 4 × 6 = 24.","hint":"Convierte una pelota a canicas pequeñas primero.","tags":["baseball"],"a":24},{"id":"log-es-5-003","topic":"logic","level":5,"type":"choice","q":"Regla: si Lola termina la tarea, juega afuera. Lola está jugando afuera. ¿Terminó la tarea?","why":"La regla dice qué pasa si termina, no que sea la única razón para jugar afuera.","hint":"¿Puede haber otra razón para estar afuera?","tags":[],"opts":["No se puede saber","Sí, seguro","No, seguro que no","Terminó solo la mitad"],"a":0},{"id":"log-es-5-004","topic":"logic","level":5,"type":"order","q":"En una balanza, el meteorito A pesa menos que B. C pesa más que B. D pesa menos que A. Ordénalos del más liviano al más pesado.","why":"D es menor que A, A menor que B y B menor que C. Une las pistas en una sola fila.","hint":"Construye la fila con una pista a la vez.","tags":["space"],"opts":["D","A","B","C"]},{"id":"log-es-5-005","topic":"logic","level":5,"type":"choice","q":"¿Qué número sigue? 3, 6, 5, 10, 9, 18, ❓","why":"Los pasos se turnan: doblar y restar 1. El último paso fue doblar (9 a 18), así que ahora restamos 1: 17.","hint":"Dos pasos distintos se turnan.","tags":[],"opts":["16","17","19","36"],"a":1},{"id":"log-es-5-006","topic":"logic","level":5,"type":"number","q":"Pedro piensa un número, lo multiplica por 3 y luego le resta 4. Obtiene 17. ¿En qué número pensó?","why":"Deshaz los pasos al revés: 17 + 4 = 21, y 21 ÷ 3 = 7.","hint":"Deshaz el último paso primero.","tags":[],"a":7},{"id":"log-es-5-007","topic":"logic","level":5,"type":"choice","q":"Repetimos A B C A B C A B C… sin parar. ¿Qué letra queda en el lugar 20?","why":"El 18 termina en C porque es múltiplo de 3. Luego el 19 es A y el 20 es B.","hint":"Usa los múltiplos de 3 para acercarte al 20.","tags":[],"opts":["A","C","D","B"],"a":3},{"id":"log-es-5-008","topic":"logic","level":5,"type":"number","q":"En un club de 20 niños, 14 aman los tiburones y 9 aman el espacio. Todos aman al menos una de las dos cosas. ¿Cuántos aman SOLO los tiburones?","why":"14 + 9 = 23, que son 3 más que 20: esos 3 aman ambas. Solo tiburones: 14 − 3 = 11.","hint":"Averigua primero cuántos aman las dos cosas.","tags":["sharks","space"],"a":11},{"id":"log-es-5-009","topic":"logic","level":5,"type":"choice","q":"Verdadero o falso: en el patrón 2, 6, 4, 8, 6, 10 el siguiente número es 8.","why":"Los pasos se turnan: +4, −2, +4, −2, +4. Ahora toca −2: 10 − 2 = 8.","hint":"Fíjate en cómo cambian los números, uno por uno.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"log-es-5-010","topic":"logic","level":5,"type":"number","q":"Mía repartió sus cromos de dinosaurios: dio la mitad a Luis, luego 3 a Ana, y le quedaron 5. ¿Cuántos cromos tenía al principio?","why":"Al revés: 5 + 3 = 8 era lo que le quedó tras dar la mitad. Si 8 es la mitad, había 16.","hint":"Retrocede desde lo que le quedó.","tags":["dinosaurs"],"a":16},{"id":"log-es-5-011","topic":"logic","level":5,"type":"choice","q":"Un partido de béisbol empezó a la 1:50 p. m. y terminó a las 4:15 p. m. ¿Cuánto duró?","why":"De 1:50 a 2:00 son 10 min, hasta las 4:00 son 2 h, y hasta las 4:15 son 15 min más.","hint":"Salta de hora en hora, no de minuto en minuto.","tags":["baseball"],"opts":["2 h 15 min","2 h 35 min","3 h 25 min","2 h 25 min"],"a":3},{"id":"log-es-5-012","topic":"logic","level":5,"type":"number","q":"Tres conchas parecen iguales, pero una pesa más. Con una balanza de dos platillos, ¿cuántas veces debes pesar como mínimo para estar seguro de cuál es?","why":"Pesa dos conchas. Si una baja, es esa; si se equilibran, es la tercera. Basta una pesada.","hint":"¿Qué pasa si los dos platillos quedan parejos?","tags":["ocean"],"a":1,"fun":true},{"id":"log-es-6-001","topic":"logic","level":6,"type":"number","q":"Unas aletas y un snorkel cuestan $13 juntos. Las aletas cuestan $11 más que el snorkel. ¿Cuántos dólares cuesta el snorkel?","why":"Si el snorkel cuesta $1, las aletas cuestan $12: suman $13 y difieren en $11. Con $2 no funciona.","hint":"Prueba tu primera idea y comprueba las dos pistas.","tags":["ocean"],"a":1},{"id":"log-es-6-002","topic":"logic","level":6,"type":"choice","q":"Alma y Beto, dos tiburones de cuento, o siempre dicen la verdad o siempre mienten. Alma dice: «Beto miente.» Beto dice: «Los dos decimos la verdad.» ¿Quién dice la verdad?","why":"Si Beto dijera la verdad, Alma también, y entonces Beto mentiría. Imposible. Beto miente y Alma acierta.","hint":"Prueba suponer que Beto dice la verdad.","tags":["sharks"],"opts":["Los dos","Solo Beto","Ninguno de los dos","Solo Alma"],"a":3},{"id":"log-es-6-003","topic":"logic","level":6,"type":"number","q":"En un torneo de béisbol, 7 equipos juegan contra todos los demás exactamente una vez. ¿Cuántos partidos se juegan en total?","why":"Cada equipo juega 6 partidos: 7 × 6 = 42. Cada partido cuenta dos veces, así que 42 ÷ 2 = 21.","hint":"Cada partido involucra a dos equipos.","tags":["baseball"],"a":21},{"id":"log-es-6-004","topic":"logic","level":6,"type":"choice","q":"Tres cajas dicen «pelotas», «guantes» y «mezcla» (pelotas y guantes juntos). TODAS las etiquetas están mal. Sacas una pelota de la caja «mezcla». ¿Qué hay en la caja «guantes»?","why":"La caja «mezcla» tiene solo pelotas. La caja «guantes» no puede ser de guantes, así que es la mezcla.","hint":"Si la etiqueta está mal, ¿qué puede haber dentro?","tags":["baseball"],"opts":["Solo guantes","Solo pelotas","Una mezcla","No se puede saber"],"a":2,"fun":true},{"id":"log-es-6-005","topic":"logic","level":6,"type":"number","q":"En un dado normal, las caras opuestas suman 7. Ves tres caras: 1, 2 y 3. ¿Cuánto suman las tres caras que NO ves?","why":"Las caras ocultas son las opuestas: 6, 5 y 4. 6 + 5 + 4 = 15.","hint":"Halla la cara opuesta de cada número que ves.","tags":[],"a":15,"fun":true},{"id":"log-es-6-006","topic":"logic","level":6,"type":"order","q":"Cinco astronautas hacen fila para subir al cohete. Hugo va primero. Kai va último. Ian va justo detrás de Ela. Jade va antes que Ela. Ordénalos de primero a último.","why":"Hugo es 1.º y Kai 5.º. Jade debe ir antes que Ela, y Ian justo después: Jade, Ela, Ian.","hint":"Coloca primero los lugares seguros.","tags":["space"],"opts":["Hugo","Jade","Ela","Ian","Kai"]},{"id":"log-es-6-007","topic":"logic","level":6,"type":"choice","q":"Dos padres y dos hijos van a pescar. Cada persona pesca un pez, y en total pescan 3 peces. ¿Cuántas personas hay?","why":"Son abuelo, padre y nieto: el padre es padre e hijo a la vez. Así hay 2 padres y 2 hijos.","hint":"¿Puede una persona ser padre e hijo a la vez?","tags":["animals"],"opts":["2","3","4","5"],"a":1,"fun":true},{"id":"log-es-6-008","topic":"logic","level":6,"type":"number","q":"Un cangrejo sube una roca de 7 pasos. De día sube 3 pasos y de noche resbala 2. ¿En qué día llega a la cima?","why":"Cada día completo gana 1 paso. Tras 4 días está en el paso 4; el día 5 sube 3 y llega al 7.","hint":"Revisa qué pasa en el último día, sin resbalar.","tags":["ocean"],"a":5},{"id":"log-es-6-009","topic":"logic","level":6,"type":"choice","q":"Verdadero o falso: si hoy es domingo, dentro de 100 días será martes.","why":"100 días son 14 semanas completas más 2 días. Domingo más 2 días es martes.","hint":"Quita las semanas completas de 7 días.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"log-es-6-010","topic":"logic","level":6,"type":"number","q":"Tomás tiene el triple de la edad de su hermana Ana. Ana tiene 4 años. ¿Cuántos años tendrá Tomás cuando Ana tenga 10?","why":"Tomás tiene 12 y le lleva 8 años a Ana. Cuando ella tenga 10, él tendrá 18.","hint":"La diferencia de edad nunca cambia.","tags":[],"a":18},{"id":"log-es-6-011","topic":"logic","level":6,"type":"choice","q":"Un cubo de 3 × 3 × 3 cubitos se pinta de rojo por fuera y luego se separa en 27 cubitos. ¿Cuántos cubitos tienen exactamente 1 cara roja?","why":"Son los cubitos del centro de cada cara. El cubo tiene 6 caras, así que hay 6.","hint":"¿Cuáles tocan una sola cara del cubo?","tags":[],"opts":["6","8","12","24"],"a":0},{"id":"log-es-6-012","topic":"logic","level":6,"type":"choice","q":"¿Cuántos cuadrados de cualquier tamaño hay en una cuadrícula de 3 × 3 casillas, contando el grande?","why":"Hay 9 cuadrados pequeños, 4 de 2 × 2 y 1 grande: 9 + 4 + 1 = 14.","hint":"Cuenta por tamaños: pequeños, medianos y el grande.","tags":[],"opts":["9","13","14","16"],"a":2,"fun":true}];
